function addLine(state,line){const p=byId(line.id);if(!p||!Number.isInteger(line.qty)||line.qty<1)throw Error('Choose a valid quantity.');const existing=state.cart.find(l=>key(l)===key(line));if((existing?.qty||0)+line.qty>stock(p,line.size,line.colour))throw Error('This quantity is not available in the selected size and colour.');if(existing)existing.qty+=line.qty;else state.cart.push({...line});}
function totals(state){const subtotal=round(state.cart.reduce((s,l)=>s+byId(l.id).price*l.qty,0));const discount=state.coupon==='NAMAA10'?round(subtotal*.1):0;const value=round(subtotal-discount);const shipping=subtotal===0?0:state.draft.delivery==='express'?95:value>=1200||state.coupon==='FREESHIP'?0:60;return{subtotal,discount,value,shipping,tax:0,total:round(value+shipping)};}
function item(l,index=0,rate=0){const p=byId(l.id),d=round(p.price*rate);return{item_id:p.id,item_name:p.name,item_brand:'Namaa',item_category:'Apparel',item_category2:p.category,item_category3:p.type,item_variant:l.colour+' / '+l.size,price:round(p.price-d),discount:d,quantity:l.qty,index};}
const items=(s)=>s.cart.map((l,i)=>item(l,i,s.coupon==='NAMAA10'?.1:0));
function validateCustomer(c){const e={};if(!c.name?.trim()||c.name.trim().length<2)e.name='Enter a fictional full name (at least 2 characters).';if(c.email?.trim()&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email.trim()))e.email='Enter a valid demo email, such as learner@example.com.';if(!/^01[0125]\d{8}$/.test(c.phone||''))e.phone='Use an 11-digit Egyptian-format demo number, such as 01000000000.';if(!c.address?.trim()||c.address.trim().length<8)e.address='Enter a fictional street and building (at least 8 characters).';if(!c.city)e.city='Choose a city.';return e;}
function placeOrder(s,id,now){const previous=s.orders.find(o=>o.checkoutId===s.draft.checkoutId);if(previous)return{order:previous,created:false};if(!s.cart.length)throw Error('Your cart is empty.');if(Object.keys(validateCustomer(s.customer)).length)throw Error('Complete the customer and delivery details.');if(!['standard','express'].includes(s.draft.delivery))throw Error('Choose a delivery option.');if(!['visa','mastercard','valu','cod'].includes(s.draft.payment))throw Error('Choose a payment method.');if(['visa','mastercard'].includes(s.draft.payment)&&s.draft.demoCardVerifiedFor!==s.draft.payment)throw Error('Validate your demo card in the payment step.');for(const l of s.cart)if(l.qty>stock(byId(l.id),l.size,l.colour))throw Error('A selected variant is no longer available.');if(s.draft.payment!=='cod'&&s.scenario==='decline')return{declined:true};if(!s.draft.checkoutId)throw Error('Start checkout again.');const o={id,checkoutId:s.draft.checkoutId,created:now,lines:s.cart.map(l=>({...l})),items:items(s),totals:totals(s),coupon:s.coupon,delivery:s.draft.delivery,payment:s.draft.payment,paymentStatus:s.draft.payment==='cod'?'pending_collection':'simulated_paid',customer:{...s.customer},refunds:[],purchaseEmitted:true};s.orders.unshift(o);s.cart=[];s.coupon='';s.draft={};return{order:o,created:true};}
function refundOrder(o,lineIndex,qty,id,now){const l=o.lines[lineIndex];if(!l||!Number.isInteger(qty)||qty<1)throw Error('Choose a valid item and refund quantity.');const used=o.refunds.filter(r=>r.lineIndex===lineIndex).reduce((n,r)=>n+r.qty,0);if(used+qty>l.qty)throw Error('Refund quantity exceeds the remaining purchased quantity.');const it={...o.items[lineIndex],quantity:qty};const r={id,created:now,lineIndex,qty,value:round(it.price*qty),item:it};o.refunds.push(r);return r;}

