// A deterministic review tool for course events. It never executes pasted code.
function auditEventPayload(input){
 const rows=Array.isArray(input)?input:[input],issues=[],ids=new Set(),purchases=new Set();
 const problem=(row,message)=>issues.push({row:row+1,message});
 if(!rows.length||rows.length>300)return{passed:false,issues:[{row:0,message:'Supply between 1 and 300 events.'}],checked:0};
 const commerce=new Set(['view_item_list','select_item','view_item','add_to_wishlist','add_to_cart','remove_from_cart','view_cart','begin_checkout','add_shipping_info','add_payment_info','purchase','refund']);
 for(let n=0;n<rows.length;n++){
  const e=rows[n];if(!e||typeof e!=='object'||Array.isArray(e)){problem(n,'Event must be an object.');continue;}
  if(typeof e.event!=='string'||!e.event.trim())problem(n,'Missing event name.');
  if(e.event_id){if(ids.has(e.event_id))problem(n,'Repeated event_id: possible duplicate emission.');ids.add(e.event_id);}
  const visit=(v,depth=0)=>{if(!v||typeof v!=='object'||depth>8)return;for(const[k,x]of Object.entries(v)){if(/^(email|phone|phone_number|address|customer|customer_name|card_number|cvv|cvc|demo_number|demo_name|user_data)$/i.test(k))problem(n,'Private field found: '+k+'. Remove it from the event.');if(typeof x==='object')visit(x,depth+1);}};visit(e);
  if(!commerce.has(e.event))continue;
  const ec=e.ecommerce;if(!ec||typeof ec!=='object'){problem(n,'Missing ecommerce object.');continue;}
  if(ec.currency!=='EGP')problem(n,'This store uses currency EGP.');
  if(ec.value!==undefined&&(typeof ec.value!=='number'||!Number.isFinite(ec.value)||ec.value<0))problem(n,'value must be a non-negative number, not a string.');
  if(!Array.isArray(ec.items)||!ec.items.length){problem(n,'Supply a non-empty items array.');continue;}
  let sum=0,canSum=true;
  for(const it of ec.items){if(!it||typeof it!=='object'){problem(n,'Every item must be an object.');canSum=false;continue;}if(!it.item_id)problem(n,'Missing stable item_id.');if(!it.item_name)problem(n,'Missing item_name.');const q=it.quantity??1;if(!Number.isInteger(q)||q<1){problem(n,'Item quantity must be a positive integer.');canSum=false;}if(typeof it.price!=='number'||!Number.isFinite(it.price)||it.price<0){problem(n,'Item price must be a non-negative number.');canSum=false;}else sum+=it.price*q;}
  if(['purchase','refund'].includes(e.event)&&typeof ec.value!=='number')problem(n,'Purchase and refund require a numeric merchandise value.');
  if(['purchase','refund'].includes(e.event)&&!ec.transaction_id)problem(n,'Missing original transaction_id.');
  if(e.event==='purchase'&&ec.transaction_id){if(purchases.has(ec.transaction_id))problem(n,'Duplicate purchase transaction_id in this input.');purchases.add(ec.transaction_id);}
  if(canSum&&typeof ec.value==='number'&&Math.abs(sum-ec.value)>.02)problem(n,'Item price × quantity does not reconcile with merchandise value. Keep shipping separate.');
 }
 return{passed:issues.length===0,issues,checked:rows.length};
}

const STORAGE='namaa.store.v3';
let s;try{s=JSON.parse(localStorage.getItem(STORAGE));if(s?.version!==3)s=initial();}catch{s=initial();}
let volatile=false;const save=()=>{try{localStorage.setItem(STORAGE,JSON.stringify(s));}catch{volatile=true;document.getElementById('storage-warning').hidden=false;}};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
window.dataLayer=window.dataLayer||[];
function track(event,data={},ec){const payload={event,event_id:uid(),demo_mode:true,training_consent:s.consent,event_schema_version:"1.1",...data,...(ec?{ecommerce:ec}:{})};if(ec)window.dataLayer.push({ecommerce:null});window.dataLayer.push(payload);s.events.push({time:new Date().toISOString(),...structuredClone(payload)});s.events=s.events.slice(-300);save();}
const ecommerce=(event,lines=s.cart,extra={})=>track(event,{}, {currency:'EGP',value:round(lines.reduce((n,l)=>n+byId(l.id).price*l.qty,0)),items:lines.map((l,i)=>item(l,i)),...extra});
const img=p=>'/namaa-gtm-classroom/assets/products/'+p.image+'.png';
const url=p=>'/namaa-gtm-classroom/products/'+p.slug+'/';
const count=()=>s.cart.reduce((n,l)=>n+l.qty,0);
window.addEventListener('storage',e=>{if(e.key===STORAGE&&e.newValue){try{const next=JSON.parse(localStorage.getItem(STORAGE)||e.newValue);if(next.version===3){s=next;updateCounts();}}catch{}}});
document.addEventListener('input',e=>{if(e.target.closest('#customer-form')){s.customer[e.target.name]=e.target.value;save();}});
let currentProduct,variant={size:'',colour:'',qty:1},checkoutStep=Number(s.draft.step)||1;
function toast(text){const e=document.getElementById('toast');e.textContent=text;e.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.hidden=true,3800);}
function updateCounts(){document.querySelectorAll('[data-cart-count]').forEach(e=>e.textContent=count());document.querySelectorAll('[data-wish-count]').forEach(e=>e.textContent=s.wishlist.length);}
const link=(href,label,cls='')=>`<a class="${cls}" href="${window.namaaHref(href)}">${label}</a>`;
const eyebrow=t=>`<p class="eyebrow">${t}</p>`;
const heading=(k,t,p='')=>`<header class="page-heading">${eyebrow(k)}<h1>${t}</h1>${p?`<p>${p}</p>`:''}</header>`;
function card(p,list,index){return `<article class="product-card" data-product-id="${p.id}"><div class="product-picture"><a id="product-link-${p.id}" data-action="select-item" data-product="${p.id}" data-list="${esc(list)}" data-index="${index}" href="${url(p)}"><img src="${img(p)}" alt="${p.name} in ${p.colours[0]}" loading="lazy"></a><span class="badge">${p.oldPrice?'Sale':p.fresh?'Just landed':p.category}</span><button class="heart ${s.wishlist.includes(p.id)?'selected':''}" data-action="wishlist" data-product="${p.id}" aria-label="${s.wishlist.includes(p.id)?'Remove':'Save'} ${p.name} ${s.wishlist.includes(p.id)?'from':'to'} wishlist" aria-pressed="${s.wishlist.includes(p.id)}">♡</button></div><div class="card-info"><small>${p.category} · ${p.type}</small><a data-action="select-item" data-product="${p.id}" data-list="${esc(list)}" data-index="${index}" href="${url(p)}"><h3>${p.name}</h3></a><p class="price">${money(p.price)} ${p.oldPrice?`<del>${money(p.oldPrice)}</del>`:''}</p><div class="swatches" aria-label="Available colours">${p.colours.map(c=>`<span title="${c}" style="--swatch:${colours[c]}"></span>`).join('')}<small>${p.sizes[0]} – ${p.sizes.at(-1)}</small></div></div></article>`;}
function grid(ps,list){queueMicrotask(()=>{if(ps.length)track('view_item_list',{}, {item_list_id:list,item_list_name:list,currency:'EGP',items:ps.map((p,i)=>({...item({id:p.id,size:p.sizes[0],colour:p.colours[0],qty:1},i),item_list_id:list,item_list_name:list}))});});return `<div class="product-grid">${ps.map((p,i)=>cardV4(p,list,i)).join('')}</div>`;}
function home(){return `<section class="hero"><div class="hero-copy">${eyebrow('SMALL CLOTHES. BIG LITTLE MOMENTS.')}<h1>For all the<br>growing up.</h1><p>Soft fabrics, thoughtful details, and everyday favourites made for their world of wonder.</p><div class="button-row">${link('/new-arrivals/','Meet the new arrivals ↗','button')}${link('/collections/','Explore collections','text-link')}</div><div class="hero-note"><span>✳</span> A little comfort. A lot of possibility.</div></div><a class="hero-image" href="/namaa-gtm-classroom/products/little-sprout-romper/" aria-label="Discover the Little Sprout Knit Romper"><img src="/namaa-gtm-classroom/assets/products/romper.png" alt="Sage cotton baby romper on a soft ivory background"><span class="hero-label">Little Beginnings<br><small>Made for their first adventures</small></span><span class="hero-stamp">SOFT<br>BY NATURE</span></a></section><div class="benefits"><span>✦ Soft, considered fabrics</span><span>↗ Free standard delivery from EGP 1,200</span><span>↺ Easy 14-day demo returns</span></div><section class="section"><div class="section-top"><div>${eyebrow('FIND THEIR NEXT FAVOURITE')}<h2>A world made for little ones.</h2></div>${link('/shop/','Shop everything →','text-link')}</div><div class="category-grid">${[['Baby','Little beginnings','romper'],['Girls','Everyday wonder','dress'],['Boys','Ready for adventure','set']].map(([c,t,i])=>`<a href="/namaa-gtm-classroom/${c.toLowerCase()}/"><img src="/namaa-gtm-classroom/assets/products/${i}.png" alt="${c} clothing collection" loading="lazy"><div><h3>${c}</h3><span>${t} ↗</span></div></a>`).join('')}</div></section><section class="section"><div class="section-top"><div>${eyebrow('FRESH FROM OUR LITTLE STUDIO')}<h2>New little favourites.</h2></div>${link('/new-arrivals/','View all new arrivals →','text-link')}</div>${grid(products.filter(p=>p.fresh).slice(0,4),'home_new_arrivals')}</section><section class="story-banner"><span class="flower">✳</span><div>${eyebrow('A LITTLE MORE NAMAA')}<h2>Growing gently.<br>Playing endlessly.</h2><p>Inspired by the small moments that become the big memories. Get to know our fictional Cairo-born children’s boutique.</p>${link('/about/','Our story ↗','text-link')}</div><div class="offer"><small>YOUR FIRST LITTLE HAUL</small><h3>A warm welcome.<br>10% off.</h3><p>Use code <strong>NAMAA10</strong> at checkout.</p>${link('/shop/','Find their favourites →','text-link')}</div></section>`;}
function shop(section){const q=new URLSearchParams(location.search),term=q.get('q')||'',cat=['baby','girls','boys'].includes(section)?section:q.get('category')||'';const contextProducts=products.filter(p=>(!cat||p.category.toLowerCase()===cat)&&(section!=="sale"||p.oldPrice)&&(section!=="new-arrivals"||p.fresh)&&(!q.get("collection")||p.collection===q.get("collection")));let ps=products.filter(p=>(!cat||p.category.toLowerCase()===cat)&&(!term||(p.name+' '+p.category+' '+p.type+' '+p.collection).toLowerCase().includes(term.toLowerCase()))&&(section!=='sale'||p.oldPrice)&&(section!=='new-arrivals'||p.fresh)&&(!q.get('collection')||p.collection===q.get('collection'))&&(!q.get('age')||p.age.includes(q.get('age')))&&(!q.get('size')||p.sizes.includes(q.get('size')))&&(!q.get('colour')||p.colours.includes(q.get('colour')))&&(!q.get('max')||p.price<=Number(q.get('max'))));const sort=q.get('sort')||'featured';if(sort==='low')ps.sort((a,b)=>a.price-b.price);if(sort==='high')ps.sort((a,b)=>b.price-a.price);if(sort==='name')ps.sort((a,b)=>a.name.localeCompare(b.name));if(term)queueMicrotask(()=>track('view_search_results',{search_term:/@|\d{7}/.test(term)?'[redacted]':term.slice(0,80),results_count:ps.length}));if(['age','size','colour','max','sort'].some(k=>q.has(k)))queueMicrotask(()=>track('product_filter',{age:q.get('age')||'',size:q.get('size')||'',colour:q.get('colour')||'',max_price:Number(q.get('max'))||null,sort,results_count:ps.length}));const title=term?'Results for “'+esc(term)+'”':cat?cat[0].toUpperCase()+cat.slice(1):section==='sale'?'Little prices. Lovely finds.':section==='new-arrivals'?'Fresh little favourites.':q.get('collection')?esc(q.get('collection')):'Made for every little moment.';const select=(name,label,opts)=>`<label>${label}<select name="${name}" id="filter-${name}"><option value="">All ${label.toLowerCase()}</option>${opts.map(v=>`<option ${q.get(name)===v?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label>`;return heading('THE NAMAA WARDROBE',title,'Thoughtful pieces for busy little days. Discover your next favourite.')+`<button id="filter-toggle" class="button secondary filter-toggle" aria-controls="catalogue-filters" aria-expanded="false">Filters & sorting ↓</button><form class="filters" id="catalogue-filters" method="get">${term?`<input type="hidden" name="q" value="${esc(term)}">`:''}${q.get('collection')?`<input type="hidden" name="collection" value="${esc(q.get('collection'))}">`:''}${select('age','Age',[...new Set(contextProducts.flatMap(p=>p.age))])}${select('size','Size',[...new Set(contextProducts.flatMap(p=>p.sizes))])}${select('colour','Colour',[...new Set(contextProducts.flatMap(p=>p.colours))])}<label>Maximum price<select name="max" id="filter-max"><option value="">Any price</option>${[400,600,800,1000].map(n=>`<option value="${n}" ${q.get('max')===String(n)?'selected':''}>Up to EGP ${n}</option>`).join('')}</select></label><label>Sort by<select name="sort" id="sort-products">${[['featured','Featured'],['low','Price: low to high'],['high','Price: high to low'],['name','Name: A to Z']].map(([v,t])=>`<option value="${v}" ${sort===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="button small" type="submit">Apply filters</button>${link(window.namaaLocalPath(),'Clear','text-link')}</form>${activeFilterChips(q)}<div class="results-summary">${ps.length} ${ps.length===1?'piece':'pieces'} to love <span>Prices in Egyptian pounds</span></div>${ps.length?grid(ps,section||'shop'):`<div class="empty"><h2>No little matches yet.</h2><p>Try a different search or clear your filters.</p>${link('/shop/','Explore all clothing','button')}</div>`}`;}
function product(p){currentProduct=p;variant={colour:p.colours[0],size:'',qty:1};queueMicrotask(()=>ecommerce('view_item',[{id:p.id,size:'Not selected',colour:p.colours[0],qty:1}]));return `<div class="breadcrumbs">${link('/','Home')} / ${link('/'+p.category.toLowerCase()+'/',p.category)} / ${p.name}</div><section class="product-detail"><div class="detail-photo"><img src="${img(p)}" alt="${p.name} in ${p.colours[0]}"><span>Shown in ${p.colours[0]}</span></div><div class="detail-copy">${eyebrow(p.collection)}<h1>${p.name}</h1><p class="detail-price">${money(p.price)} ${p.oldPrice?`<del>${money(p.oldPrice)}</del><span class="tag">Save ${money(p.oldPrice-p.price)}</span>`:''}</p><p>${p.description}</p><div id="variant-controls"></div><p class="stock" id="variant-stock">Choose your size to see availability.</p><label class="qty-label" for="product-quantity">Quantity <input type="number" id="product-quantity" min="1" max="8" value="1"></label><div class="button-row"><button id="add-to-cart" class="button" data-action="add-cart">Add to cart</button><button id="product-wishlist" class="button secondary" data-action="wishlist" data-product="${p.id}">♡ ${s.wishlist.includes(p.id)?'Saved':'Save'}</button></div><p class="small-text">Free standard delivery from EGP 1,200 · ${link('/size-guide/','Find their size')}</p><details open><summary>Fabric & care</summary><p>${p.fabric}</p></details><details><summary>Delivery & returns</summary><p>Standard delivery EGP 60, or free on discounted merchandise totals of EGP 1,200+. Express EGP 95. Easy 14-day demo returns.</p>${link('/shipping/','Delivery details →')} ${link('/returns/','Returns details →')}</details></div></section><section class="section"><div class="section-top"><div>${eyebrow('A LITTLE SOMETHING TO GO WITH IT')}<h2>Lovely together.</h2></div></div>${grid(products.filter(x=>x.id!==p.id&&(x.category===p.category||x.collection===p.collection)).slice(0,3),'related_products')}</section>`;}
function renderVariants(){if(!currentProduct)return;const p=currentProduct;document.getElementById('variant-controls').innerHTML=`<fieldset><legend>Colour: <strong>${variant.colour}</strong></legend><div class="options">${p.colours.map(c=>`<button type="button" data-action="colour" data-value="${c}" aria-pressed="${variant.colour===c}" class="colour-option ${variant.colour===c?'active':''}"><i style="--swatch:${colours[c]}"></i>${c}</button>`).join('')}</div></fieldset><fieldset><legend>Size ${link('/size-guide/','Size guide ↗','text-link')}</legend><div class="options">${p.sizes.map(z=>`<button type="button" data-action="size" data-value="${z}" aria-pressed="${variant.size===z}" ${stock(p,z,variant.colour)===0?'disabled':''} class="size-option ${variant.size===z?'active':''}">${z}${stock(p,z,variant.colour)===0?' · sold out':''}</button>`).join('')}</div></fieldset>`;const available=stock(p,variant.size,variant.colour);document.getElementById('variant-stock').textContent=!variant.size?'Choose your size to see availability.':available?available<=2?`Only ${available} left in this size`:'In stock · ready for little adventures':'This variant is sold out. Choose another size or colour.';document.getElementById('add-to-cart').disabled=!!variant.size&&!available;}
function cartLines(drawer=false){return s.cart.map((l,i)=>{const p=byId(l.id);return `<article class="cart-line"><a href="${url(p)}"><img src="${img(p)}" alt="${p.name}"></a><div><a href="${url(p)}"><h3>${p.name}</h3></a><p>${l.colour} / ${l.size}</p><p>${money(p.price)}</p><div class="line-controls"><label>Quantity <input type="number" aria-label="Quantity for ${p.name}" data-action="cart-quantity" data-index="${i}" min="1" max="${stock(p,l.size,l.colour)}" value="${l.qty}"></label><button class="text-button" data-action="remove-cart" data-index="${i}">Remove</button></div></div><strong>${money(p.price*l.qty)}</strong></article>`;}).join('');}
function summary(order){const t=order?.totals||totals(s),coupon=order?.coupon||s.coupon;return `<dl class="totals"><div><dt>Subtotal</dt><dd>${money(t.subtotal)}</dd></div><div><dt>Discount ${coupon?'('+coupon+')':''}</dt><dd>−${money(t.discount)}</dd></div><div><dt>${order?.delivery==='express'||(!order&&s.draft.delivery==='express')?'Express':'Standard'} delivery</dt><dd>${t.shipping?money(t.shipping):'Free'}</dd></div><div><dt>Tax</dt><dd>Included in prices</dd></div><div class="grand-total"><dt>Total</dt><dd>${money(t.total)}</dd></div></dl>`;}
function couponForm(){return `<form id="discount-form" class="coupon-form"><label for="discount-code">Have a little treat?</label><div><input id="discount-code" name="coupon" placeholder="Discount code" value="${esc(s.coupon)}"><button class="button secondary small" type="submit">Apply</button></div><small>NAMAA10: 10% off · FREESHIP: standard delivery free. One code per order.</small>${s.coupon?'<button type="button" class="text-button" data-action="remove-coupon">Remove code</button>':''}<p id="coupon-message" class="error" role="status"></p></form>`;}
function cart(){queueMicrotask(()=>ecommerce('view_cart'));return heading('A FEW LITTLE FAVOURITES','Your shopping cart.')+(s.cart.length?`<div class="two-column"><section>${cartLines()}${link('/shop/','← Keep exploring','text-link')}</section><aside class="order-summary"><h2>A lovely little order.</h2>${summary()}${couponForm()}<a href="/namaa-gtm-classroom/checkout/" id="checkout-button" class="button wide">Continue to checkout →</a><p class="small-text">Demo checkout. No real payment or delivery.</p></aside></div>`:empty('Your cart is waiting for a little joy.'));}
function empty(text){return `<div class="empty"><span class="flower">✳</span><h2>${text}</h2><p>Find something soft, playful and just their size.</p>${link('/shop/','Explore the wardrobe','button')}</div>`;}
function drawer(){const e=document.getElementById('cart-dialog');e.innerHTML=`<div class="drawer-heading"><h2>Your cart <small>(${count()})</small></h2><button class="icon-button" data-action="close-dialog" aria-label="Close shopping cart">×</button></div>${s.cart.length?`${cartLines(true)}<div class="drawer-bottom">${shippingProgress()}${summary()}${link('/cart/','View full cart','button secondary wide')}${link('/checkout/','Checkout →','button wide')}</div>`:empty('A little room for favourites.')}`;if(!e.open)e.showModal();}
function startCheckout(){if(!s.draft.checkoutId){s.draft={checkoutId:uid(),step:1,layoutVersion:2,delivery:'standard',payment:''};checkoutStep=1;save();ecommerce('begin_checkout',s.cart,{...totals(s),value:totals(s).value,items:items(s),coupon:s.coupon});}else if(s.draft.layoutVersion!==2){s.draft.layoutVersion=2;s.draft.step=1;s.draft.payment='';delete s.draft.demoCardVerifiedFor;checkoutStep=1;save();}}
function field(name,label,type='text',placeholder=''){return `<label for="customer-${name}">${label}<input id="customer-${name}" name="${name}" type="${type}" value="${esc(s.customer[name]||'')}" placeholder="${placeholder}" aria-describedby="error-${name}" autocomplete="off"><span id="error-${name}" class="error" role="status"></span></label>`;}
function checkout(){if(!s.cart.length)return heading('YOUR LITTLE ORDER','Checkout')+empty('Your cart is empty.');startCheckout();const step=checkoutStep;return heading('ONE LITTLE STEP CLOSER','Let’s make it theirs.','Fictional details and test cards only. No real payment or delivery.')+`<nav class="checkout-steps" aria-label="Checkout steps">${['Payment','Details','Delivery','Review'].map((t,i)=>`<button data-action="checkout-step" data-step="${i+1}" ${i+1>step?'disabled':''} aria-current="${step===i+1?'step':'false'}"><span>${i+1}</span>${t}</button>`).join('')}</nav><div class="two-column"><section class="checkout-panel">${step===1?`<h2>How would you like to pay?</h2><p>Choose your payment method first. All payments are simulated.</p><form id="payment-choice-form" novalidate><fieldset class="payment-options"><legend>Payment method</legend>${[['visa','Visa','Test card payment'],['mastercard','Mastercard','Test card payment'],['valu','Valu','Simulated approval · no real financing'],['cod','Cash on delivery','Payment pending collection']].map(([v,t,d])=>`<label class="radio-card"><input id="payment-${v}" type="radio" name="payment" value="${v}" ${s.draft.payment===v?'checked':''}><span><strong>${t}</strong><small>${d}</small></span></label>`).join('')}</fieldset>${['visa','mastercard'].includes(s.draft.payment)?`<div class="demo-card-panel"><h3>${paymentLabel(s.draft.payment)} · test card only</h3><p>Never enter a real card or real cardholder details. Use this test number:<strong id="test-card-number">${s.draft.payment==='visa'?'4242 4242 4242 4242':'5555 5555 5555 4444'}</strong></p><label for="demo-card-number">Demo card number<input id="demo-card-number" name="demo_number" type="text" inputmode="numeric" maxlength="23" autocomplete="off" placeholder="Displayed test number" aria-describedby="demo-number-error"><span id="demo-number-error" class="error" role="status"></span></label><label for="demo-card-name">Fictional name on card<input id="demo-card-name" name="demo_name" type="text" maxlength="60" autocomplete="off" placeholder="Demo Shopper" aria-describedby="demo-name-error"><span id="demo-name-error" class="error" role="status"></span></label><p class="small-text">Test entries are discarded after validation. Refreshing this step requires re-entry.</p></div>`:s.draft.payment==='valu'?`<div class="demo-card-panel"><h3>Valu demo approval</h3><p>Approval is simulated when you place the order. No Valu account, OTP, national ID or real instalment agreement is needed.</p></div>`:s.draft.payment==='cod'?`<p class="demo-payment-note">Your simulated order will show payment pending collection.</p>`:''}<p id="payment-choice-error" class="error" role="alert"></p><button id="continue-details" class="button" type="submit">Continue to details →</button></form>`:step===2?`<h2>Your demo details</h2><p class="small-text">For class practice, use fictional details. Email is optional; leave it blank or use learner@example.com.</p><form id="customer-form" novalidate><div class="form-grid">${field('name','Full name','text','Demo Shopper')}${field('email','Email (optional)','email','learner@example.com')}${field('phone','Mobile number','tel','01000000000')}<label for="customer-city">City<select name="city" id="customer-city"><option value="">Choose a city</option>${['Cairo','Giza','Alexandria','Mansoura','Other governorates'].map(v=>`<option ${s.customer.city===v?'selected':''}>${v}</option>`).join('')}</select><span class="error" id="error-city" role="status"></span></label><div class="full-width">${field('address','Street, building & apartment','text','12 Demo Street, Apartment 4')}</div></div><button type="submit" class="button" id="continue-delivery">Continue to delivery →</button></form>`:step===3?`<h2>A little closer to your door.</h2><form id="delivery-form"><fieldset class="delivery-options"><legend>Choose a demo delivery option</legend>${[['standard','Standard delivery','3–5 business days','EGP 60 · free from EGP 1,200 after discounts'],['express','Express delivery','1–2 business days','EGP 95']].map(([v,t,d,c])=>`<label class="radio-card"><input type="radio" name="delivery" value="${v}" ${s.draft.delivery===v?'checked':''}><span><strong>${t}</strong><small>${d}</small><small>${c}</small></span></label>`).join('')}</fieldset><button class="button" type="submit" id="continue-payment">Review order →</button></form>`:`<h2>One last little look.</h2><div class="review-details"><p><strong>${esc(s.customer.name)}</strong><br>${esc(s.customer.address)}, ${esc(s.customer.city)}</p><button class="text-button" data-action="checkout-step" data-step="2">Edit details</button></div><p>${s.draft.delivery==='express'?'Express · 1–2':'Standard · 3–5'} business days (simulated)</p>${s.cart.map(l=>`<div class="review-line"><span>${byId(l.id).name}<small>${l.colour} / ${l.size} × ${l.qty}</small></span><strong>${money(byId(l.id).price*l.qty)}</strong></div>`).join('')}<p><strong>Payment: ${paymentLabel(s.draft.payment)}</strong> · demo only <button type="button" class="text-button" data-action="checkout-step" data-step="1">Change payment</button></p><form id="payment-form" novalidate><input type="hidden" name="checkoutId" value="${s.draft.checkoutId}"><input type="hidden" name="payment" value="${s.draft.payment}"><p class="demo-payment-note">Nothing is charged or shipped. ${s.draft.payment==='cod'?'Payment remains pending collection.':s.draft.payment==='valu'?'Valu approval is simulated; no financing agreement is created.':'Your test card was validated. No card entry is saved.'}</p><label class="terms"><input id="demo-confirm" name="demoConfirm" type="checkbox"> I understand this is a demo order using fictional details.</label><p id="payment-error" class="error" role="alert"></p><button id="place-order" class="button wide" type="submit">${s.draft.payment==='cod'?'Place demo COD order':'Simulate payment & place order'} · ${money(totals(s).total)}</button></form>`}</section><aside class="order-summary"><h2>In your cart</h2>${s.cart.map(l=>`<div class="mini-line"><img src="${img(byId(l.id))}" alt=""><p>${byId(l.id).name}<small>${l.colour} / ${l.size} × ${l.qty}</small></p></div>`).join('')}${summary()}${couponForm()}${link('/cart/','Edit shopping cart','text-link')}</aside></div>`;}
function confirmation(){const id=new URLSearchParams(location.search).get('order'),o=s.orders.find(o=>o.id===id);if(!o)return heading('DEMO ORDER','Order not found','Orders are stored in the browser where they were placed.')+link('/shop/','Back to shopping','button');return `<section class="confirmation-heading"><span class="success-mark">✓</span>${eyebrow('A LITTLE THANK YOU')}<h1>Your demo order is in.</h1><p>No real payment was taken. No items will be shipped.</p><strong id="order-number">${o.id}</strong><p>${new Date(o.created).toLocaleString('en-GB')}</p><span class="status-tag">${o.paymentStatus==='pending_collection'?'Cash on delivery · payment pending':'Payment successful · simulated'}</span></section><div class="two-column"><section><h2>Little favourites on the list.</h2>${o.lines.map(l=>`<article class="cart-line"><img src="${img(byId(l.id))}" alt="${byId(l.id).name}"><div><h3>${byId(l.id).name}</h3><p>${l.colour} / ${l.size} · Quantity ${l.qty}</p></div><strong>${money(byId(l.id).price*l.qty)}</strong></article>`).join('')}<h3>Demo delivery</h3><p>${esc(o.customer.name)}<br>${esc(o.customer.address)}, ${esc(o.customer.city)}</p><p>${o.delivery==='express'?'Express, 1–2':'Standard, 3–5'} business days · simulated only</p><div class="button-row">${link('/shop/','Keep exploring','button')}${link('/returns/','Returns & help','text-link')}</div></section><aside class="order-summary"><h2>Order summary</h2>${summary(o)}<p>Payment: ${paymentLabel(o.payment)}</p>${o.refunds.length?`<p>Demo merchandise refunds: ${money(o.refunds.reduce((n,r)=>n+r.value,0))}</p>`:''}<p class="small-text">This confirmation is saved only in this browser. Refreshing it will not create another order.</p></aside></div>`;}
const docs={
 about:['Our little story.','Namaa means growth. Our fictional Cairo-born boutique celebrates the little moments of growing up: first steps, messy afternoons and the everyday adventure of being a child.','<h2>Comfort comes first.</h2><p>Our demonstration wardrobe features breathable cotton, gentle colours and practical shapes. Thoughtful details make these fictional products feel ready for real life.</p><h2>A store built for learning.</h2><p>Namaa is a fictional ecommerce business used in eYouth’s Google Tag Manager course. Products, prices, orders, payments and delivery promises are illustrative. There is no trading business behind this checkout.</p>'],
 shipping:['A little closer to your door.','A clear guide to our simulated delivery options.','<h2>Standard delivery</h2><p>EGP 60, with an illustrative 3–5 business day estimate. Free when your merchandise total after discounts reaches EGP 1,200. The FREESHIP code also removes standard delivery charges.</p><h2>Express delivery</h2><p>EGP 95, with an illustrative 1–2 business day estimate. Free shipping offers do not apply to express delivery.</p><p>All listed Egyptian cities use the same demo rates. Nothing is actually dispatched.</p>'],
 returns:['A little room to change your mind.','Our fictional 14-day returns policy keeps the shopping journey easy to understand.','<h2>How a demo return works</h2><p>Keep your demo order number and choose which item and quantity you want to return. In class, your instructor records the return in the separate instructor area.</p><h2>Refund scope</h2><p>Demo refunds cover the discounted merchandise value only. Delivery is not refunded. Partial and full merchandise returns are supported, and a quantity cannot be refunded twice.</p><p>No money moves. For cash-on-delivery orders, a return is a simulated reversal of accepted merchandise revenue, not a card refund.</p>'],
 privacy:['Your privacy, in plain words.','Use fictional customer details throughout this training store.','<h2>What stays on your device</h2><p>Your basket, wishlist, customer draft, orders, preferences and a bounded diagnostic event log are stored in this browser’s local storage. There is no customer database or real payment processor. Anyone using this same browser profile may see that data.</p><h2>Measurement</h2><p>The store creates a local data layer for course exercises. Customer names, email addresses, phone numbers and shipping addresses are excluded from event payloads. The current configuration status is shown in the instructor studio. A local event is not evidence that a GTM tag ran or that Google Analytics received it.</p><p>If a training GTM container is configured later, it loads only after you allow optional training measurement. Declining keeps the storefront functional and blocks that loader. Consent changes reload the page to stop already loaded tags; local event inspection remains available. This is a classroom consent exercise, not a production consent-management platform.</p><h2>Clear your data</h2><p>Use the clear browser data control below to erase Namaa orders, cart, wishlist, customer details and local event history for this browser. No data from other websites is affected.</p><button class="button secondary" data-action="clear-personal">Clear my Namaa browser data</button><button class="text-button" data-action="privacy-settings">Measurement preferences</button>'],
 faqs:['Little questions, clear answers.','Everything you need for your Namaa demo shopping trip.','<details open><summary>Can I buy these clothes?</summary><p>No. Namaa is a fictional course store. All transactions and deliveries are simulated.</p></details><details><summary>Which discount codes work?</summary><p>NAMAA10 gives 10% off merchandise. FREESHIP removes standard delivery fees. Use one code per order. Express delivery always costs EGP 95.</p></details><details><summary>Why is a size unavailable?</summary><p>Stock is modelled by size and colour. Try another combination; the selection shows availability before adding to your cart.</p></details><details><summary>What happens if a demo payment is declined?</summary><p>Your cart and entered details remain intact. Use the retry option or choose another demo payment method. The instructor can select repeatable success or decline scenarios.</p></details><details><summary>Where are my orders saved?</summary><p>Only in the browser profile where you placed them. Clearing site storage removes them.</p></details><details><summary>Does changing colour update the photo?</summary><p>The catalogue photograph shows the labelled first colour. Available colour choices are listed separately; this demo has one photograph per style.</p></details>'],
 'size-guide':['A just-right little fit.','Illustrative body measurements in centimetres. Sizes are guidance only.','<h2>Baby</h2><div class="table-wrap"><table><tr><th>Size</th><th>Height</th><th>Chest</th></tr><tr><td>0–3m</td><td>56–62</td><td>40–43</td></tr><tr><td>3–6m</td><td>62–68</td><td>43–46</td></tr><tr><td>6–12m</td><td>68–80</td><td>46–49</td></tr><tr><td>12–18m</td><td>80–86</td><td>49–51</td></tr></table></div><h2>Kids</h2><div class="table-wrap"><table><tr><th>Size</th><th>Height</th><th>Chest</th></tr><tr><td>2–3y</td><td>92–98</td><td>53–55</td></tr><tr><td>4–5y</td><td>104–110</td><td>57–59</td></tr><tr><td>6–7y</td><td>116–122</td><td>61–63</td></tr><tr><td>8–9y</td><td>128–134</td><td>65–68</td></tr><tr><td>10–11y</td><td>140–146</td><td>71–74</td></tr></table></div><p>Measure around the fullest part of the chest. If between sizes, choose the larger size for room to grow.</p>' ]
};
function contact(){return heading('WE’RE HERE FOR THE LITTLE THINGS','Say hello.','Fictional support for a fictional store. Please use demo details.')+`<div class="two-column"><form id="contact-form" class="checkout-panel"><label>Your demo name<input name="name" required minlength="2" placeholder="Demo Shopper"></label><label>Demo email<input name="email" type="email" required placeholder="learner@example.com"></label><label>Topic<select name="topic"><option>Order question</option><option>Sizing help</option><option>Delivery question</option><option>Returns</option></select></label><label>Your message<textarea name="message" required minlength="10" rows="5" placeholder="Tell us about your demo question"></textarea></label><button class="button" type="submit">Send demo message</button><p id="contact-result" role="status"></p></form><aside><h2>A friendly little note.</h2><p>This form displays a simulated confirmation. It does not send an email or create a support ticket.</p><p>For exercise use: hello@namaa.example<br>Illustrative hours: Sunday–Thursday, 9am–5pm.</p>${link('/faqs/','Read our FAQs →','text-link')}</aside></div>`;}
function collections(){return heading('THE LITTLE EDITS','A collection for every chapter.','From first adventures to the next big little discovery.')+`<div class="collection-grid">${[...new Set(products.map(p=>p.collection))].map((c,i)=>{const p=products.find(p=>p.collection===c);return `<a href="/namaa-gtm-classroom/shop/?collection=${encodeURIComponent(c)}"><img src="${img(p)}" alt="${c} collection"><div><small>THE NAMAA EDIT · 0${i+1}</small><h2>${c}</h2><span>Explore the collection ↗</span></div></a>`;}).join('')}</div>`;}
function instructor(){return heading('NAMAA / INSTRUCTOR STUDIO','A reliable place to rehearse.','Controls affect only this browser. This public demo area is not an authenticated admin system.')+`<div class="instructor-grid"><section class="panel"><h2>Payment test scenario</h2><p>Current: <strong id="current-scenario">${s.scenario==='decline'?'Decline Visa / Mastercard / Valu':'Successful Visa / Mastercard / Valu'}</strong></p><label for="test-scenario">Next Visa, Mastercard and Valu attempts<select id="test-scenario"><option value="success" ${s.scenario==='success'?'selected':''}>Always succeed</option><option value="decline" ${s.scenario==='decline'?'selected':''}>Always decline (retry can succeed)</option></select></label><p>Cash on delivery always accepts the order with payment pending. A declined attempt never generates purchase. “Retry demo payment” permits one successful attempt without changing this global scenario.</p><button class="button secondary" data-action="seed-cart">Load a practice basket</button><p class="small-text">Replaces basket with 2 tees and 1 romper, clears checkout and coupon; keeps orders and wishlist.</p>${link('/checkout/','Open checkout →','text-link')}</section><section class="panel"><h2>Repeat the exercise</h2><div class="stack"><button class="button secondary" data-action="reset-cart">Reset cart & checkout</button><button class="button secondary" data-action="reset-customer">Reset customer details</button><button class="button secondary" data-action="reset-orders">Reset demo orders</button><button class="button secondary" data-action="reset-events">Clear event log</button><button class="button danger" data-action="reset-all">Reset all Namaa data</button></div><p class="small-text">Each reset asks for confirmation. Reset all clears wishlist, consent and scenarios too. These actions do not delete anything already collected by an external analytics service.</p></section></div><section class="panel"><h2>Demo order & refund ledger</h2><p>Refund discounted merchandise only, by item and quantity. Delivery is excluded. Repeated refunds cannot exceed the purchased quantity.</p>${s.orders.length?s.orders.map(o=>`<details class="order-record"><summary>${o.id} · ${money(o.totals.total)} · ${o.paymentStatus}</summary><p>${o.lines.map(l=>esc(byId(l.id).name)+' × '+l.qty).join(', ')}</p><form class="refund-form" data-order="${o.id}"><label>Purchased item<select name="line">${o.lines.map((l,i)=>`<option value="${i}">${byId(l.id).name} / ${l.colour} / ${l.size} · ${l.qty-o.refunds.filter(r=>r.lineIndex===i).reduce((n,r)=>n+r.qty,0)} remaining</option>`).join('')}</select></label><label>Quantity<input name="qty" type="number" min="1" value="1" required></label><button class="button small" type="submit">Record demo refund</button><p class="error" role="status"></p></form><p>${o.refunds.length?o.refunds.map(r=>`${r.id} · ${r.qty} item(s) · ${money(r.value)}`).join('<br>'):'No refunds yet.'}</p>${link('/confirmation/?order='+o.id,'View confirmation →','text-link')}</details>`).join(''):'<p>No orders in this browser yet.</p>'}</section><section class="panel"><div class="section-top"><h2>Local event inspector</h2><div class="button-row"><button class="button secondary small" data-action="refresh-events">Refresh</button><button class="button secondary small" data-action="export-events">Download JSON</button></div></div><p id="tracking-status"><strong>Data layer implemented. GTM and GA4 receipt unverified.</strong> ${window.NAMAA_CONFIG?.gtmId?'A configured GTM loader is available after consent; no receipt evidence is implied.':'No GTM ID configured; no Google measurement script is loaded.'}</p><p>Most recent 300 events, saved per browser. Checkout PII is excluded. Reloading this page does not replay historical events into the data layer.</p><div id="event-inspector">${eventInspector()}</div></section><section class="panel technical"><h2>Measurement & AI lab guide</h2><p>Read the <a href="/namaa-gtm-classroom/measurement-plan.json">machine-readable measurement plan</a>, <a href="/namaa-gtm-classroom/assets/catalog.mjs">catalogue contract</a>, and <a href="/namaa-gtm-classroom/resources/">course resources</a>. Stable selectors use <code>id</code>, <code>data-action</code> and <code>data-product-id</code>; do not target generated CSS classes.</p><h3>Business questions to investigate</h3><ul><li>Which collections lead to product discovery and cart additions?</li><li>Which sizes and colours create availability friction?</li><li>Where do shoppers abandon checkout, and does simulated payment failure explain it?</li><li>How do discounts and returns change merchandise revenue?</li></ul><h3>GTM implementation boundary</h3><p>Events are pushed through <code>window.dataLayer.push</code>. Before ecommerce events, the ecommerce object is cleared. Set up Custom Event triggers and Data Layer Variables in your dedicated training container. Configure a GA4 event tag to read ecommerce data. Use Tag Assistant to verify tag execution and GA4 DebugView to verify receipt separately. Do not create a second purchase tag using confirmation-page views.</p><h3>Values & identity</h3><p>Currency EGP; numeric unit prices. <code>ecommerce.value</code> is discounted merchandise revenue excluding shipping. Item discounts are per unit. <code>transaction_id</code> is the demo order ID. Cash on delivery is an accepted purchase with <code>payment_status=pending_collection</code>. Declines emit only <code>payment_failed</code>. Refunds use the original transaction ID and a unique <code>refund_id</code>.</p><h3>Purchase deduplication</h3><p>Order creation saves the order, checkout identity and purchase claim in one local-storage snapshot before emitting purchase. A repeat submission for that checkout returns the saved order; confirmation rendering never emits purchase. This browser-local guard is an exercise in at-most-once emission, not server-side delivery assurance. Do not clear demo orders mid-attempt. Storage failure blocks order placement. Concurrent submission uses Web Locks where supported.</p><h3>AI-assisted exercise</h3><p>Give an AI the measurement plan and a redacted event export. Ask it to propose GTM triggers, variables and a QA matrix. Check currency, item structure, consent, failure cases and duplicates manually before importing anything. Never upload customer details, account credentials or production containers.</p><h3>Lesson scenarios</h3><ol><li>Beginner: product link versus contact link; inspect Click URL.</li><li>Variables: compare Page URL and Click URL in the same interaction.</li><li>Ecommerce: add 2 tees, use NAMAA10, choose express delivery, complete a simulated card payment.</li><li>Failure: force decline, confirm no purchase, retry successfully.</li><li>Quality: refresh confirmation; confirm no extra purchase. Refund one unit, then the remainder; reject an excessive refund.</li><li>Privacy: decline measurement, repeat the journey, inspect local data without external collection.</li></ol></section>`;}
function eventInspector(){return s.events.length?`<p>${s.events.length} recorded events · purchases: <strong id="purchase-event-count">${s.events.filter(e=>e.event==='purchase').length}</strong> · refunds: ${s.events.filter(e=>e.event==='refund').length}</p><div class="event-log">${s.events.slice().reverse().map(e=>`<details><summary>${e.event} <small>${new Date(e.time).toLocaleTimeString('en-GB')}${e.ecommerce?.transaction_id?' · '+e.ecommerce.transaction_id:''}</small></summary><pre>${esc(JSON.stringify(e,null,2))}</pre></details>`).join('')}</div>`:'<p>No local events recorded.</p>';}
function resources(){return heading('EYOUTH / GOOGLE TAG MANAGER','Your classroom toolkit.','Use the store for real browser interactions. Use the separate concept lab for an explicit simulation.')+`<div class="instructor-grid"><section class="panel"><h2>Namaa practice store</h2><p>A complete children’s clothing journey, from discovery to simulated purchase.</p>${link('/','Explore the store →','button')}</section><section class="panel"><h2>Module 1 workbook</h2><p>Current children’s clothing example, definitions, eight exercises and a ten-question understanding check.</p>${link('/resources/student-workbook.html','Open workbook →','text-link')}</section><section class="panel"><h2>Module 1 presentation</h2><p>68 slides: 66 core slides and two optional store references. Updated to the current clothing store.</p>${link('/resources/module-1/','Open presentation →','button')}${link('/resources/store-orientation.html','Store reference & worked example →','text-link')}</section><section class="panel"><h2>Concept lab</h2><p>A standalone logic simulation. It does not prove GTM execution or analytics receipt.</p>${link('/resources/concept-lab.html','Open simulation →','text-link')}</section><section class="panel"><h2>Tracking opportunities</h2><p>Browse → product → Add to cart → payment choice → details → delivery → review → demo order → refund.</p>${link('/measurement-plan.json','Read measurement contract →','text-link')}</section></div>`;}
function render(){let path=decodeURIComponent(window.namaaLocalPath()).replace(/\.html$/,'').split('/').filter(Boolean),route=path[0]||'home',html;if(route==='home')html=homeV4();else if(['shop','baby','girls','boys','new-arrivals','sale'].includes(route))html=shop(route);else if(route==='products'){const p=products.find(p=>p.slug===path[1]);html=p?product(p):heading('THE NAMAA WARDROBE','That little piece has moved.')+link('/shop/','Explore the clothing collection','button');}else if(route==='collections')html=collections();else if(route==='cart')html=cart();else if(route==='checkout')html=checkout();else if(route==='confirmation')html=confirmation();else if(route==='wishlist')html=heading('SAVED FOR A LITTLE LATER','Your favourites.')+(s.wishlist.length?grid(s.wishlist.map(byId).filter(Boolean),'wishlist'):empty('Save a little something you love.'));else if(route==='contact')html=contact();else if(route==='instructor')html=path[1]==='coverage'?coverageV4():path[1]==='labs'?labsV4():instructor();else if(route==='orders')html=ordersV4();else if(route==='resources')html=resources();else if(docs[route]){const[t,p,b]=docs[route];html=heading('THE NAMAA DETAILS',t,p)+`<article class="prose">${b}</article>`;}else if(route==='help')html=heading('A LITTLE HELP','How can we help?')+link('/faqs/','Read our FAQs','button');else if(route==='edge-cases')html=heading('TRIGGER LOGIC LAB','When “contains” is too broad.','Predict which link leads to a product. A product path can also appear in a help-page query string.')+`<div class="button-row">${link('/products/little-sprout-romper/','Intended product destination','button')}${link('/help/?return=/products/little-sprout-romper/','Help with product path in query','button secondary')}</div>`;else html=heading('A LITTLE LOST?','Let’s find your way.')+link('/','Back to Namaa','button');document.getElementById('main').innerHTML=html;document.title=(document.querySelector('h1')?.innerText.replaceAll('\n',' ')||'Little clothes, big moments')+' | Namaa';updateCounts();renderVariants();enhanceRenderedPage(route);document.querySelectorAll("#primary-nav>a").forEach(a=>{if(a.getAttribute("href")==="/namaa-gtm-classroom/"+route+"/")a.setAttribute("aria-current","page");});}
function consentUI(){const e=document.getElementById('consent-banner');e.hidden=s.consent!=='unset';}
function loadMeasurement(){const id=window.NAMAA_CONFIG?.gtmId;if(s.consent!=='granted'||!/^GTM-[A-Z0-9]+$/.test(id||''))return;window.gtag?.('consent','update',{analytics_storage:'granted',ad_storage:'denied',ad_user_data:'denied',ad_personalization:'denied'});window.dataLayer.push({'gtm.start':Date.now(),event:'gtm.js'});const script=document.createElement('script');script.src='https://www.googletagmanager.com/gtm.js?id='+encodeURIComponent(id);script.async=true;document.head.append(script);}
let pendingReset;function reset(action,confirmed=false){const messages={'reset-cart':'Clear the basket, coupon and checkout draft?','reset-customer':'Clear saved customer details and return checkout to its first step?','reset-orders':'Clear demo orders and their refund history? Existing analytics collections cannot be erased here.','reset-events':'Clear this browser’s local diagnostic event log?','reset-all':'Clear all Namaa browser data, including orders and preferences?','clear-personal':'Clear all Namaa browser data?'};if(!confirmed){pendingReset=action;let d=document.getElementById("reset-dialog");if(!d){d=document.createElement("dialog");d.id="reset-dialog";d.setAttribute("aria-label","Confirm demo data reset");document.body.append(d);}d.innerHTML=`<h2>Reset demo data?</h2><p>${esc(messages[action])}</p><div class="button-row"><button class="button danger" data-action="confirm-reset">Confirm reset</button><button class="button secondary" data-action="close-dialog">Keep data</button></div>`;d.showModal();return;}if(['reset-all','clear-personal'].includes(action)){s=initial();save();location.href='/namaa-gtm-classroom/';return;}if(action==='reset-cart'){s.cart=[];s.coupon='';s.draft={};}if(action==='reset-customer'){s.customer={};s.draft.step=1;checkoutStep=1;}if(action==='reset-orders')s.orders=[];if(action==='reset-events')s.events=[];save();render();toast('Namaa demo data reset.');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;try{
 if(a==='select-item'){const p=byId(b.dataset.product);track('select_item',{}, {item_list_id:b.dataset.list,item_list_name:b.dataset.list,items:[{...item({id:p.id,size:'Not selected',colour:p.colours[0],qty:1},Number(b.dataset.index)),item_list_id:b.dataset.list}]});}
 if(a==='wishlist'){const id=b.dataset.product,existed=s.wishlist.includes(id);s.wishlist=existed?s.wishlist.filter(x=>x!==id):[...s.wishlist,id];save();const p=byId(id);ecommerce(existed?'remove_from_wishlist':'add_to_wishlist',[{id,size:currentProduct?.id===id?variant.size||'Not selected':'Not selected',colour:currentProduct?.id===id?variant.colour:p.colours[0],qty:1}]);updateCounts();b.setAttribute('aria-pressed',String(!existed));b.classList.toggle('selected',!existed);if(b.id==='product-wishlist')b.textContent=existed?'♡ Save':'♡ Saved';else b.setAttribute('aria-label',(existed?'Save ':'Remove ')+p.name+(existed?' to wishlist':' from wishlist'));if(window.namaaLocalPath().startsWith('/wishlist'))render();toast(existed?'Removed from favourites.':'Saved for a little later.');}
 if(a==='size'||a==='colour'){variant[a]=b.dataset.value;track('select_variant',{item_id:currentProduct.id,size:variant.size||'Not selected',colour:variant.colour,availability:variant.size?(stock(currentProduct,variant.size,variant.colour)?'in_stock':'out_of_stock'):'size_not_selected'});renderVariants();}
 if(a==='add-cart'){if(!variant.size){toast('Choose a size before adding to your cart.');document.querySelector('[data-action="size"]')?.focus();return;}const qty=Number(document.getElementById('product-quantity').value),line={id:currentProduct.id,size:variant.size,colour:variant.colour,qty};addLine(s,line);save();ecommerce('add_to_cart',[line]);updateCounts();drawer();}
 if(a==='open-cart'){ecommerce('view_cart');drawer();}
 if(a==='close-dialog')b.closest('dialog').close();
 if(a==='remove-cart'){const l=s.cart.splice(Number(b.dataset.index),1)[0];if(l)ecommerce('remove_from_cart',[l]);save();updateCounts();if(document.getElementById('cart-dialog').open)drawer();else render();}
 if(a==='remove-coupon'){s.coupon='';save();render();}
 if(a==='checkout-step'){checkoutStep=Number(b.dataset.step);s.draft.step=checkoutStep;save();render();}
 if(a==='retry-payment'){s.draft.retrySuccess=true;save();track('payment_retry',{payment_type:s.draft.payment});const err=document.getElementById('payment-error');err.textContent='Ready to retry. Confirm the demo checkbox and place your order again.';document.getElementById('place-order').focus();}
 if(a==='privacy-settings'){s.consent='unset';save();consentUI();document.getElementById('consent-banner').scrollIntoView({block:'end'});}
 if(a==='consent'){s.consent=b.dataset.value;save();track('consent_choice',{analytics_choice:s.consent});location.reload();}
 if(['reset-cart','reset-customer','reset-orders','reset-events','reset-all','clear-personal'].includes(a))reset(a);if(a==='confirm-reset'){b.closest('dialog').close();reset(pendingReset,true);}
 if(a==='seed-cart'){s.cart=[];addLine(s,{id:'NM-K001',size:'4–5y',colour:'Sky',qty:2});addLine(s,{id:'NM-B001',size:'6–12m',colour:'Sage',qty:1});s.coupon='';s.draft={};save();updateCounts();toast('Practice basket loaded.');}
 if(a==='refresh-events')document.getElementById('event-inspector').innerHTML=eventInspector();
 if(a==='export-events'){const blob=new Blob([JSON.stringify(s.events,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),l=document.createElement('a');l.href=u;l.download='namaa-demo-events.json';l.click();setTimeout(()=>URL.revokeObjectURL(u),5000);}
 if(a==='mobile-menu'){const nav=document.getElementById('primary-nav');nav.classList.toggle('expanded');b.setAttribute('aria-expanded',String(nav.classList.contains('expanded')));}
 }catch(err){toast(err.message);}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='test-scenario'){s.scenario=el.value;save();document.getElementById('current-scenario').textContent=el.value==='decline'?'Decline Visa / Mastercard / Valu':'Successful Visa / Mastercard / Valu';toast('Payment scenario saved.');}if(el.dataset.action==='cart-quantity'){const i=Number(el.dataset.index),l=s.cart[i],old=l.qty,n=Number(el.value);if(!Number.isInteger(n)||n<1||n>stock(byId(l.id),l.size,l.colour)){el.value=old;toast('Choose a quantity within the available stock.');return;}l.qty=n;save();if(n!==old)ecommerce(n>old?'add_to_cart':'remove_from_cart',[{...l,qty:Math.abs(n-old)}]);updateCounts();if(document.getElementById('cart-dialog').open)drawer();else render();}if(el.name==='payment'){s.draft.payment=el.value;delete s.draft.demoCardVerifiedFor;delete s.draft.retrySuccess;save();render();document.getElementById('payment-'+el.value)?.focus();ecommerce('add_payment_info',s.cart,{currency:'EGP',value:totals(s).value,coupon:s.coupon,items:items(s),payment_type:el.value});}if(el.name==='delivery'){s.draft.delivery=el.value;save();render();}});
let submitting=false;
document.addEventListener('submit',async e=>{const f=e.target;if(!['discount-form','payment-choice-form','customer-form','delivery-form','payment-form','contact-form'].includes(f.id)&&!f.classList.contains('refund-form'))return;e.preventDefault();const data=Object.fromEntries(new FormData(f));try{
 if(f.id==='discount-form'){const code=data.coupon.trim().toUpperCase();if(!['NAMAA10','FREESHIP'].includes(code)){document.getElementById('coupon-message').textContent='This code is not valid. Try NAMAA10 or FREESHIP.';track('coupon_rejected',{reason:'invalid_code'});return;}s.coupon=code;save();track('coupon_applied',{coupon:code});render();toast('A little treat applied.');}
 if(f.id==='payment-choice-form'){const method=data.payment;if(!['visa','mastercard','valu','cod'].includes(method)){document.getElementById('payment-choice-error').textContent='Choose a payment method to continue.';track('checkout_validation_error',{step:'payment_selection',fields:['payment']});return;}if(['visa','mastercard'].includes(method)){const errors=validateDemoCard(method,data.demo_number,data.demo_name);for(const [n,id] of [['demo_number','demo-number-error'],['demo_name','demo-name-error']]){document.getElementById(id).textContent=errors[n]||'';f.elements[n].setAttribute('aria-invalid',String(!!errors[n]));}if(Object.keys(errors).length){track('checkout_validation_error',{step:'demo_card',fields:Object.keys(errors)});f.elements[Object.keys(errors)[0]].focus();return;}s.draft.demoCardVerifiedFor=method;f.elements.demo_number.value='';f.elements.demo_name.value='';}s.draft.payment=method;s.draft.step=2;checkoutStep=2;save();track('checkout_step_completed',{checkout_step:'payment_selection',payment_type:method});render();window.scrollTo(0,0);}
 if(f.id==='customer-form'){const errors=validateCustomer(data);for(const n of ['name','email','phone','address','city']){document.getElementById('error-'+n).textContent=errors[n]||'';document.getElementById('customer-'+n).setAttribute('aria-invalid',String(!!errors[n]));}if(Object.keys(errors).length){track('checkout_validation_error',{step:'customer',fields:Object.keys(errors)});document.getElementById('customer-'+Object.keys(errors)[0]).focus();return;}s.customer=data;s.draft.step=3;checkoutStep=3;save();track('checkout_step_completed',{checkout_step:'customer_details'});render();window.scrollTo(0,0);}
 if(f.id==='delivery-form'){s.draft.delivery=data.delivery;s.draft.step=4;checkoutStep=4;save();ecommerce('add_shipping_info',s.cart,{value:totals(s).value,items:items(s),coupon:s.coupon,shipping_tier:data.delivery});render();window.scrollTo(0,0);}
 if(f.id==='payment-form'){if(submitting)return;const error=document.getElementById('payment-error');if(!data.payment||!data.demoConfirm){error.textContent=!data.payment?'Choose a demo payment method.':'Confirm that you understand this is a demo order.';track('checkout_validation_error',{step:'payment',fields:[!data.payment?'payment':'demo_confirmation']});return;}if(volatile){error.textContent='Browser storage is unavailable. Enable site storage before placing a demo order.';return;}submitting=true;document.getElementById('place-order').disabled=true;error.textContent=data.payment==='cod'?'Creating your demo order…':'Simulating '+paymentLabel(data.payment)+' authorization… No real payment is processed.';await new Promise(resolve=>setTimeout(resolve,800));s.draft.payment=data.payment;const commit=()=>{const latest=localStorage.getItem(STORAGE);if(latest){const parsed=JSON.parse(latest);if(parsed.version===3)s=parsed;}const existing=s.orders.find(o=>o.checkoutId===data.checkoutId);if(existing){location.href='/namaa-gtm-classroom/confirmation/?order='+existing.id;return;}if(s.draft.checkoutId!==data.checkoutId)throw Error('This checkout changed in another tab. Reload and review your current bag.');const scenario=s.scenario;if(s.draft.retrySuccess)s.scenario='success';let result;try{result=placeOrder(s,'NM-'+new Date().toISOString().slice(0,10).replaceAll('-','')+'-'+uid().slice(0,8).toUpperCase(),new Date().toISOString());}finally{s.scenario=scenario;}if(result.declined){delete s.draft.retrySuccess;save();track('payment_failed',{payment_type:data.payment,reason:'simulated_decline'});error.innerHTML='Demo payment declined. Your cart and details are safe. <button type="button" class="text-button" data-action="retry-payment">Retry demo payment</button> or choose cash on delivery.';return;}save();if(volatile)throw Error('Order could not be persisted. Enable browser storage and reset this attempt.');if(result.created){const o=result.order;track('purchase',{payment_type:o.payment,payment_status:o.paymentStatus},{transaction_id:o.id,currency:'EGP',value:o.totals.value,shipping:o.totals.shipping,tax:0,coupon:o.coupon,items:o.items});}location.href='/namaa-gtm-classroom/confirmation/?order='+result.order.id;};try{if(navigator.locks)await navigator.locks.request('namaa-checkout',commit);else commit();}finally{submitting=false;const b=document.getElementById('place-order');if(b)b.disabled=false;}}
 if(f.id==='contact-form'){document.getElementById('contact-result').textContent='Demo message received on this screen. No email or support ticket was sent.';track('contact_submit',{topic:data.topic});f.reset();}
 if(f.classList.contains('refund-form')){const o=s.orders.find(o=>o.id===f.dataset.order),r=refundOrder(o,Number(data.line),Number(data.qty),'RF-'+uid().slice(0,8).toUpperCase(),new Date().toISOString());save();track('refund',{refund_id:r.id,payment_status:o.paymentStatus},{transaction_id:o.id,currency:'EGP',value:r.value,items:[r.item]});render();toast('Demo refund recorded: '+money(r.value));}
 }catch(err){if(f.classList.contains('refund-form'))f.querySelector('.error').textContent=err.message;else if(f.id==='payment-form'){document.getElementById('payment-error').textContent=err.message;submitting=false;document.getElementById('place-order').disabled=false;}else toast(err.message);}});
function bootStore(){loadMeasurement();render();consentUI();}

const icons={search:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>',bag:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/></svg>',heart:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 5c-3-3-7-1-8 1-1-2-5-4-8-1-4 4 0 8 8 14 8-6 12-10 8-14Z"/></svg>'};
let quickProduct,quickVariant={size:'',colour:'',qty:1};
function activeFilterChips(q){return '<div class="active-filters">'+['age','size','colour','max','sort'].filter(k=>q.get(k)&&!(k==='sort'&&q.get(k)==='featured')).map(k=>{const next=new URLSearchParams(q);next.delete(k);const value=k==='sort'?({low:'Price: low to high',high:'Price: high to low',name:'Name: A to Z'}[q.get(k)]||q.get(k)):q.get(k);return `<a href="/namaa-gtm-classroom${window.namaaLocalPath()}?${esc(next.toString())}" aria-label="Remove ${k} filter">${k==='max'?'Up to EGP ':''}${esc(value)} <span>×</span></a>`;}).join('')+'</div>';}
function homeV4(){return `<section class="campaign-hero" aria-label="New season campaign"><img class="campaign-photo" src="/namaa-gtm-classroom/assets/campaign-play.png" alt="Two fictional children enjoying a playful moment in rose and blue Namaa-inspired outfits"><div class="campaign-copy"><span class="campaign-kicker">A NEW SEASON OF LITTLE ADVENTURES</span><h1>Big days.<br>Little outfits.</h1><p>Play-ready pieces. Feel-good fabrics.<br>Made for their wonderfully busy world.</p><div class="button-row"><a id="hero-shop-new" class="button" href="/namaa-gtm-classroom/new-arrivals/" data-action="promotion" data-promo="new_season">Explore new arrivals ${icons.bag}</a><a class="button secondary" href="/namaa-gtm-classroom/shop/">Shop all clothing →</a></div><div class="campaign-tags"><span>Soft cotton</span><span>Baby to 11 years</span><span>Made for play</span></div></div><span class="campaign-sticker">LET THEM<br>BE LITTLE ✳</span></section><div class="service-ribbon"><a href="/namaa-gtm-classroom/shipping/">${icons.bag}<span>Free standard delivery<strong>From EGP 1,200 after discounts</strong></span></a><a href="/namaa-gtm-classroom/returns/"><span class="service-symbol">↺</span><span>A little peace of mind<strong>14-day demo returns</strong></span></a><a href="/namaa-gtm-classroom/size-guide/"><span class="service-symbol">✂</span><span>Find their happy fit<strong>Easy size & age guides</strong></span></a></div><section class="section shortcuts"><div class="section-top"><div>${eyebrow('THEIR WORLD, THEIR WARDROBE')}<h2>Small people. <em>Big personalities.</em></h2></div>${link('/collections/','Explore collections →','text-link')}</div><div class="shortcut-grid">${[['Baby','0–18 months','romper','/baby/'],['Girls','2–9 years','dress','/girls/'],['Boys','2–11 years','tee','/boys/'],['Soft layers','Cosy little favourites','cardigan','/shop/?collection=Soft%20Layers'],['Little prices','Lovely sale finds','dungarees','/sale/']].map(([n,a,i,u])=>`<a href="${window.namaaHref(u)}"><span class="shortcut-photo"><img src="/namaa-gtm-classroom/assets/products/${i}.png" alt="${n} clothing" loading="lazy"></span><h3>${n}</h3><small>${a}</small></a>`).join('')}</div></section><section class="section"><div class="section-top"><div>${eyebrow('FRESH FINDS FOR EVERY LITTLE DAY')}<h2>Just landed. <em>Already loved.</em></h2></div>${link('/new-arrivals/','Shop new arrivals →','text-link')}</div>${grid(products.filter(p=>p.fresh).slice(0,4),'home_new_arrivals')}</section><section class="promo-duo"><a class="promo-tile pink" href="/namaa-gtm-classroom/sale/" data-action="promotion" data-promo="little_prices"><div>${eyebrow('LITTLE PRICES, BIG SMILES')}<h2>Good days.<br>Great little finds.</h2><p>Selected favourites at softer prices.</p><span class="button">Explore the sale →</span></div><img src="/namaa-gtm-classroom/assets/products/dungarees.png" alt="Sandcastle dungarees on sale" loading="lazy"></a><a class="promo-tile blue" href="/namaa-gtm-classroom/shop/?collection=Play%20All%20Day" data-action="promotion" data-promo="play_all_day"><div>${eyebrow('THE PLAY ALL DAY EDIT')}<h2>Ready, set,<br>anything.</h2><p>Easy outfits for endless adventures.</p><span class="button secondary">Shop the edit →</span></div><img src="/namaa-gtm-classroom/assets/products/tee.png" alt="Sky blue Sunshine Cotton Tee" loading="lazy"></a></section><section class="section"><div class="section-top"><div>${eyebrow('ROOM TO GROW, REASONS TO SMILE')}<h2>Shop by their <em>next chapter.</em></h2></div></div><div class="age-grid">${[['0–2 years','Tiny beginnings','For their first discoveries.'],['2–5 years','Little explorers','For make-believe and messy days.'],['6–11 years','Big little adventures','For a world that gets bigger every day.']].map(([a,n,t])=>`<a href="/namaa-gtm-classroom/shop/?age=${encodeURIComponent(a)}"><small>${a}</small><h3>${n}</h3><p>${t}</p><span>Find their favourites ↗</span></a>`).join('')}</div></section><section class="welcome-card"><div><span class="campaign-kicker">A LITTLE HELLO FROM NAMAA</span><h2>Their first Namaa adventure?<br>Here’s a little welcome.</h2><p>Take 10% off merchandise with <strong>NAMAA10</strong>. One code per order.</p></div><a href="/namaa-gtm-classroom/shop/" class="button" data-action="promotion" data-promo="welcome_10">Find their favourites →</a></section>`;}
function cardV4(p,list,index){const sale=p.oldPrice?Math.round((1-p.price/p.oldPrice)*100):0;return `<article class="product-card" data-product-id="${p.id}"><div class="product-picture"><a id="product-link-${p.id}" data-action="select-item" data-product="${p.id}" data-list="${esc(list)}" data-index="${index}" href="${url(p)}"><img src="${img(p)}" alt="${p.name} in ${p.colours[0]}" loading="lazy"></a><span class="badge ${sale?'sale-badge':''}">${sale?'−'+sale+'%':p.fresh?'New arrival':p.category}</span><button class="heart ${s.wishlist.includes(p.id)?'selected':''}" data-action="wishlist" data-product="${p.id}" aria-label="${s.wishlist.includes(p.id)?'Remove':'Save'} ${p.name} ${s.wishlist.includes(p.id)?'from':'to'} wishlist" aria-pressed="${s.wishlist.includes(p.id)}">${icons.heart}</button><button class="quick-view" data-action="quick-view" data-product="${p.id}" aria-label="Quick shop ${p.name}">Quick shop <span>+</span></button></div><div class="card-info"><small>${p.category} · ${p.type}</small><a data-action="select-item" data-product="${p.id}" data-list="${esc(list)}" data-index="${index}" href="${url(p)}"><h3>${p.name}</h3></a><p class="price">${money(p.price)} ${p.oldPrice?`<del>${money(p.oldPrice)}</del>`:''}</p><div class="swatches" aria-label="Available colours">${p.colours.map(c=>`<span title="${c}" style="--swatch:${colours[c]}"></span>`).join('')}<small>${p.sizes[0]} – ${p.sizes.at(-1)}</small></div></div></article>`;}
function shippingProgress(){const t=totals(s),left=round(Math.max(0,1200-t.value));return `<div class="shipping-progress" role="status"><p>${s.coupon==='FREESHIP'?'Your standard delivery is free with FREESHIP.':left?'You’re '+money(left)+' away from free standard delivery.':'Lovely! You’ve unlocked free standard delivery.'}</p><progress max="1200" value="${Math.min(1200,t.value)}" aria-label="Progress toward free standard delivery"></progress><small>Express delivery remains EGP 95.</small></div>`;}
function showQuickProduct(id){quickProduct=byId(id);quickVariant={size:'',colour:quickProduct.colours[0],qty:1};ecommerce('view_item',[{id,size:'Not selected',colour:quickVariant.colour,qty:1}],{item_view_source:'quick_shop'});renderQuick();document.getElementById('quick-dialog').showModal();}
function renderQuick(){let d=document.getElementById('quick-dialog');if(!d){d=document.createElement('dialog');d.id='quick-dialog';d.setAttribute('aria-label','Quick shop product');document.body.append(d);}const p=quickProduct;d.innerHTML=`<div class="drawer-heading"><h2>One little favourite.</h2><button class="icon-button" data-action="close-dialog" aria-label="Close quick shop">×</button></div><div class="quick-layout"><img src="${img(p)}" alt="${p.name} in ${p.colours[0]}"><div>${eyebrow(p.category)}<h3>${p.name}</h3><p class="detail-price">${money(p.price)}</p><p class="small-text">Photo shows ${p.colours[0]}.</p><label for="quick-colour">Colour<select id="quick-colour">${p.colours.map(c=>`<option ${c===quickVariant.colour?'selected':''}>${c}</option>`).join('')}</select></label><label for="quick-size">Size<select id="quick-size"><option value="">Choose a size</option>${p.sizes.map(z=>`<option value="${z}" ${z===quickVariant.size?'selected':''} ${!stock(p,z,quickVariant.colour)?'disabled':''}>${z}${!stock(p,z,quickVariant.colour)?' · sold out':''}</option>`).join('')}</select></label><label for="quick-quantity">Quantity<input id="quick-quantity" type="number" min="1" max="8" value="${quickVariant.qty}"></label><p id="quick-error" class="error" role="alert"></p><button class="button wide" id="quick-add" data-action="quick-add">Add to cart</button><a class="text-link" href="${url(p)}">See all product details →</a></div></div>`;}
function ordersV4(){return heading('YOUR NAMAA ADVENTURES','Your demo orders.','Saved in this browser only. No real payments or deliveries.')+(s.orders.length?`<div class="orders-list">${s.orders.map(o=>`<article class="panel order-tile"><div><small>${new Date(o.created).toLocaleDateString('en-GB')}</small><h2>${o.id}</h2><p>${o.lines.reduce((n,l)=>n+l.qty,0)} ${o.lines.reduce((n,l)=>n+l.qty,0)===1?'item':'items'} · ${money(o.totals.total)}</p><span class="status-tag">${o.paymentStatus==='pending_collection'?'Payment pending · COD':'Simulated payment successful'}</span></div><a class="button secondary" href="/namaa-gtm-classroom/confirmation/?order=${o.id}">View order →</a></article>`).join('')}</div>`:empty('Your first little order is waiting.'));}
function coverageV4(){return heading('EYOUTH / COURSE COVERAGE','From first click to final handover.','A practical scenario map. Website fixtures, GTM execution and analytics receipt are separate evidence.')+`<div class="lab-nav"><a class="button" href="/namaa-gtm-classroom/instructor/labs/">Open practice lab →</a><a class="button secondary" href="/namaa-gtm-classroom/instructor/">Instructor studio</a><a class="button secondary" href="/namaa-gtm-classroom/course-scenarios.json" download>Download scenario matrix</a><a class="text-link" href="/namaa-gtm-classroom/measurement-plan.json">Event contract</a></div><div class="coverage-grid">${courseScenarios.map(x=>`<article class="panel coverage-card"><small>${x.stage}</small><span class="coverage-status ${x.status.includes('External')?'pending':''}">${x.status}</span><h2>${x.title}</h2><p>${x.task}</p><div class="coverage-evidence"><strong>Evidence & boundary</strong><p>${x.evidence}</p></div>${x.events.length?`<p class="event-chips">${x.events.map(e=>`<code>${e}</code>`).join(' ')}</p>`:''}<a class="text-link" href="${window.namaaHref(x.path)}">Open exercise environment →</a></article>`).join('')}</div><section class="panel"><h2>What still needs real external configuration</h2><p>Dedicated GTM and GA4 IDs, Tag Assistant/DebugView verification, consent tag configuration, a second owned origin for cross-domain measurement, server GTM infrastructure, and authorized GTM API access. No website-only exercise proves any of these.</p><p>For sequencing and custom-template lessons, use lab events as test inputs inside your training container. The website does not execute unreviewed custom tags or AI-generated code.</p></section>`;}
function labsV4(){return heading('EYOUTH / MEASUREMENT PRACTICE LAB','One store. More ways to learn.','Instructor-selected exercises, kept separate from the student shopping journey. Only fictional details belong here.')+`<nav class="lab-nav"><a href="/namaa-gtm-classroom/instructor/" class="button secondary">Instructor studio</a><a href="/namaa-gtm-classroom/instructor/coverage/" class="button">Course scenario map</a><a href="#forms">Forms</a><a href="#triggers">Triggers</a><a href="#advanced">SPA & iframe</a><a href="#diagnostics">Diagnostics</a></nav><section class="panel" id="forms"><span class="coverage-status">WORKING EXERCISE</span><h2>Forms, leads & downloads</h2><p>Submit a bad value, then learner@example.com. A successful signup is stored once per browser; the email itself is not stored or logged.</p>${newsletterForm('lab')}<div class="button-row"><a class="button secondary" href="/namaa-gtm-classroom/assets/namaa-size-guide.csv" download data-action="download-guide">Download size guide CSV ↓</a><a class="text-link" href="/namaa-gtm-classroom/contact/">Open contact-form exercise →</a><button class="text-button" data-action="reset-newsletter">Reset signup exercise</button></div></section><section class="panel" id="triggers"><h2>Clicks, time & scroll</h2><p>Arm a 10-second foreground engagement timer. Hidden-tab time does not count. Scroll through this page to generate 25/50/75/90% lab depth events once each per page load.</p><div class="button-row"><button class="button" id="engagement-start" data-action="arm-timer">Start 10-second exercise</button><a class="button secondary" href="/namaa-gtm-classroom/products/little-sprout-romper/">Matching product link</a><a class="text-link" href="/namaa-gtm-classroom/contact/">Nonmatching contact link</a><a class="text-link" href="/namaa-gtm-classroom/help/?return=/products/little-sprout-romper/">Help URL with product path</a></div><p id="timer-status" role="status">Timer not started.</p></section><section class="panel" id="advanced"><h2>Real SPA history changes</h2><p>The controls below use history.pushState without reloading the document. Use browser Back/Forward afterwards. The website emits virtual_page_view; configure your GTM history-change strategy separately and avoid sending both as duplicate GA4 page views.</p><div class="button-row">${['discover','size','care'].map(r=>`<button class="button secondary" data-action="spa-route" data-route="${r}">${{discover:'Discover the edit',size:'Find a size',care:'Fabric care'}[r]}</button>`).join('')}</div><div id="spa-panel" class="spa-panel" role="region" aria-live="polite"></div><h3>Embedded form</h3><p>A real same-origin iframe. A verified postMessage bridge reports a successful submission to the parent. No name or contact details are required.</p><iframe id="lesson-frame" title="Embedded fit advice form" src="/namaa-gtm-classroom/instructor/frame/" loading="lazy"></iframe><p id="frame-result" role="status">No embedded submission yet.</p></section><section class="panel" id="diagnostics"><h2>Safe diagnostic faults</h2><p>These deliberately bad fixtures use lab-prefixed event names. They cannot create fake purchase or refund revenue. Inspect the payload and explain the repair.</p><div class="button-row"><button class="button secondary" data-action="lab-good">Emit valid payload</button><button class="button secondary" data-action="lab-bad">Emit malformed payload</button><button class="button secondary" data-action="lab-duplicate">Emit duplicate probe</button></div><pre id="lab-output">Choose a payload to inspect.</pre><p>The duplicate probe intentionally sends the same event_id twice. A downstream tag needs an explicit deduplication policy; purchase protection is a separate, existing order safeguard.</p><h3>Promotion & discovery</h3><p>Observe a campaign on the homepage, click it, quick-shop a product, then continue into checkout. Compare list selection, quick view, promotion selection and cart changes.</p><a class="button secondary" href="/namaa-gtm-classroom/">Open campaign homepage →</a></section><section class="panel"><h2>Consent, transport & AI boundaries</h2><p>Allow and decline preferences affect the optional GTM loader. Store events stay inspectable locally. Production Consent Mode/CMP, cross-domain linker configuration and server transport must be built and tested externally.</p><div class="button-row"><button class="button secondary" data-action="privacy-settings">Review measurement preferences</button><a class="text-link" href="/namaa-gtm-classroom/instructor/coverage/">Read the full course coverage →</a></div></section>`;}
function newsletterForm(where){return `<form class="newsletter-form" id="newsletter-${where}" data-newsletter="${where}" novalidate><label for="newsletter-email-${where}">${where==='footer'?'Join our little world':'Demo newsletter signup'}</label><p>${where==='footer'?'A little style inspiration. A little welcome. Use a fictional email for this demo.':''}</p><div><input id="newsletter-email-${where}" name="email" type="email" placeholder="learner@example.com" aria-label="${where==='footer'?'Newsletter':'Lab newsletter'} demo email" required><button class="button" type="submit">Join the family →</button></div><p class="newsletter-result" role="status"></p></form>`;}
function enhanceRenderedPage(route){if(route==='instructor'&&!window.namaaLocalPath().includes('/labs')&&!window.namaaLocalPath().includes('/coverage')){document.querySelector('#main .page-heading').insertAdjacentHTML('afterend','<nav class="lab-nav"><a class="button" href="/namaa-gtm-classroom/instructor/coverage/">Course scenario map →</a><a class="button secondary" href="/namaa-gtm-classroom/instructor/labs/">Interactive practice lab</a></nav>');}if(['cart','checkout'].includes(route)&&s.cart.length){document.querySelector('.order-summary')?.insertAdjacentHTML('afterbegin',shippingProgress());}if(route==='home'){const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){const id=e.target.dataset.promo;if(id){track('view_promotion',{}, {promotion_id:id,promotion_name:id.replaceAll('_',' '),creative_slot:e.target.id||'homepage'});observer.unobserve(e.target);}}},{threshold:.45});document.querySelectorAll('[data-action="promotion"]').forEach(el=>observer.observe(el));}if(route==='instructor'&&window.namaaLocalPath().includes('/labs'))bootLabPage();if(route==='shop'||['baby','girls','boys','new-arrivals','sale'].includes(route)){const filters=document.getElementById('catalogue-filters');filters?.setAttribute('aria-label','Product filters');document.getElementById('filter-toggle')?.addEventListener('click',()=>{const open=filters.classList.toggle('filters-open');document.getElementById('filter-toggle').setAttribute('aria-expanded',String(open));});}}
function bootEnhancements(){document.querySelector(".footer-grid>div:last-child").insertAdjacentHTML("beforeend",'<a href="/namaa-gtm-classroom/orders/">My demo orders</a>');document.querySelector('.header-search button').innerHTML=icons.search;document.querySelector('#cart-toggle').insertAdjacentHTML('afterbegin',icons.bag);document.querySelector('#wishlist-link').insertAdjacentHTML('afterbegin',icons.heart);document.querySelector('.footer-grid').insertAdjacentHTML('beforebegin',`<section class="newsletter-band">${newsletterForm('footer')}<div><h2>A happy little wardrobe.<br>A brighter little world.</h2><p>Fictional store. Real opportunities to learn.</p></div></section>`);document.addEventListener('click',enhancedClick);document.addEventListener('change',enhancedChange);document.addEventListener('submit',enhancedSubmit);document.addEventListener('focusin',e=>{const f=e.target.closest('[data-newsletter]');if(f&&!f.dataset.started){f.dataset.started='1';track('form_start',{form_id:f.id});}});}
function enhancedClick(e){const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(a==='quick-view')showQuickProduct(el.dataset.product);if(a==='quick-add'){try{quickVariant.qty=Number(document.getElementById('quick-quantity').value);if(!quickVariant.size)throw Error('Choose a size to add this favourite.');const line={id:quickProduct.id,...quickVariant};addLine(s,line);save();ecommerce('add_to_cart',[line]);document.getElementById('quick-dialog').close();updateCounts();drawer();}catch(err){document.getElementById('quick-error').textContent=err.message;}}if(a==='promotion')track('select_promotion',{}, {promotion_id:el.dataset.promo,promotion_name:el.dataset.promo.replaceAll('_',' '),creative_slot:el.id||'homepage'});if(a==='download-guide')track('file_download',{file_name:'namaa-size-guide.csv',file_extension:'csv',link_url:'/assets/namaa-size-guide.csv'});if(a==='reset-newsletter'){s.newsletterJoined=false;save();toast('Newsletter exercise reset.');}if(a==='spa-route')spaRoute(el.dataset.route,true);if(a==='arm-timer')armTimer();if(a==='lab-good'||a==='lab-bad'){const good=a==='lab-good',ec={currency:good?'EGP':'XYZ',value:good?549:'five hundred',items:[good?item({id:'NM-B001',size:'6–12m',colour:'Sage',qty:1}):{item_name:'Missing ID fixture',price:'unknown'}]};track('lab_payload',{fixture:good?'valid':'malformed'},ec);document.getElementById('lab-output').textContent=JSON.stringify({event:'lab_payload',ecommerce:ec},null,2);}if(a==='lab-duplicate'){const id=uid(),payload={event_id:id,fixture:'intentional_duplicate'};track('lab_duplicate_probe',payload);track('lab_duplicate_probe',payload);document.getElementById('lab-output').textContent='Two lab_duplicate_probe events emitted with the same event_id: '+id;}}
function enhancedChange(e){if(['quick-size','quick-colour'].includes(e.target.id)){quickVariant.size=document.getElementById('quick-size').value;quickVariant.colour=document.getElementById('quick-colour').value;quickVariant.qty=Number(document.getElementById('quick-quantity').value)||1;if(quickVariant.size&&!stock(quickProduct,quickVariant.size,quickVariant.colour))quickVariant.size='';track('select_variant',{item_id:quickProduct.id,size:quickVariant.size||'Not selected',colour:quickVariant.colour,source:'quick_shop'});const focusId=e.target.id;renderQuick();document.getElementById(focusId).focus();}}
function enhancedSubmit(e){const f=e.target;if(!f.matches('[data-newsletter]'))return;e.preventDefault();const email=new FormData(f).get('email')||'',result=f.querySelector('.newsletter-result');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){result.textContent='Enter a valid fictional email, for example learner@example.com.';f.querySelector('input').setAttribute('aria-invalid','true');track('form_validation_error',{form_id:f.id,fields:['email']});return;}f.querySelector('input').setAttribute('aria-invalid','false');if(s.newsletterJoined){result.textContent='You’re already part of this demo family. No second signup was recorded.';return;}s.newsletterJoined=true;save();track('generate_lead',{form_id:f.id,lead_type:'demo_newsletter',value:0,currency:'EGP'});result.textContent='You’re in! Demo signup complete. No email will be sent.';f.reset();}
function spaRoute(route,push){const content={discover:['The play-all-day edit','Explore soft cotton pieces for their next adventure.'],size:['Room for growing','Choose by height and chest measurements, then check the product size guide.'],care:['A little fabric care','Wash gently at 30°C. Reshape knits while damp and dry flat.']};if(!content[route])route='discover';if(push){const u=new URL(location.href);u.searchParams.set('lesson_view',route);history.pushState({namaaLesson:route},'',u);}document.getElementById('spa-panel').innerHTML=`<small>SPA VIEW · ${route}</small><h3>${content[route][0]}</h3><p>${content[route][1]}</p>`;track('virtual_page_view',{page_path:'/instructor/labs/?lesson_view='+route,page_title:content[route][0],navigation_type:push?'push_state':'initial_or_pop_state'});}
let labTimer,foregroundMs=0,lastTick=0;function armTimer(){clearInterval(labTimer);foregroundMs=0;lastTick=performance.now();document.getElementById('timer-status').textContent='Timer running: 0 / 10 visible seconds.';labTimer=setInterval(()=>{const now=performance.now();if(!document.hidden)foregroundMs+=Math.min(1000,now-lastTick);lastTick=now;const el=document.getElementById('timer-status');if(!el){clearInterval(labTimer);return;}el.textContent='Timer running: '+Math.min(10,Math.floor(foregroundMs/1000))+' / 10 visible seconds.';if(foregroundMs>=10000){clearInterval(labTimer);track('lab_engaged',{engagement_time_msec:10000,lab_id:'trigger_lab'});el.textContent='Complete: lab_engaged emitted after 10 visible seconds.';}},250);}
function bootLabPage(){spaRoute(new URLSearchParams(location.search).get('lesson_view')||'discover',false);window.addEventListener('popstate',()=>spaRoute(new URLSearchParams(location.search).get('lesson_view')||'discover',false));const depths=new Set();window.addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-innerHeight;if(max<=0)return;const depth=Math.round(scrollY/max*100);for(const threshold of [25,50,75,90])if(depth>=threshold&&!depths.has(threshold)){depths.add(threshold);track('lab_scroll',{percent_scrolled:threshold,lab_id:'trigger_lab'});}},{passive:true});window.addEventListener('message',e=>{const f=document.getElementById('lesson-frame');if(e.origin!==location.origin||e.source!==f?.contentWindow||e.data?.type!=='namaa_fit_submit')return;if(!['baby','kids'].includes(e.data.age_group))return;track('embedded_form_submit',{form_id:'embedded_fit_advice',age_group:e.data.age_group});document.getElementById('frame-result').textContent='Embedded submission received by the parent. No personal details were sent.';});}

let navOpen='',suggestionsOpen=false,fitObserver;
const additionalEvents={video_start:'Native HTML5 demo video begins',video_progress:'Video playback reaches 25/50/75 percent',video_complete:'Native HTML5 demo video ends',video_pause:'Playback paused before completion (custom)',outbound_click:'External reference link selected (custom)',campaign_landing:'Allowlisted classroom campaign arrives (custom)',fit_panel_view:'Size advice panel becomes visible (custom)',payload_audit:'Local schema review completed; no pasted values exported (custom)'};
function categoryMenu(category){const ps=products.filter(p=>p.category.toLowerCase()===category),p=ps[0],sizes=[...new Set(ps.flatMap(p=>p.sizes))];return `<div class="menu-links"><small>THE ${category.toUpperCase()} WARDROBE</small><a class="menu-title" href="/namaa-gtm-classroom/${category}/">Shop all ${category} →</a>${[...new Set(ps.map(p=>p.type))].map(t=>`<a href="/namaa-gtm-classroom/shop/?category=${category}&q=${encodeURIComponent(t)}">${t}</a>`).join('')}<a href="/namaa-gtm-classroom/new-arrivals/">New little favourites</a></div><div class="menu-links"><small>FIND THEIR SIZE</small>${sizes.map(z=>`<a href="/namaa-gtm-classroom/${category}/?size=${encodeURIComponent(z)}">${z}</a>`).join('')}<a class="text-link" href="/namaa-gtm-classroom/size-guide/">Size guide ↗</a></div><a class="menu-feature" href="${url(p)}"><img src="${img(p)}" alt="${p.name}" loading="lazy"><span>${p.collection}<strong>Meet their next favourite ↗</strong></span></a>`;}
function setupNavigationV7(){
 for(const category of ['baby','girls','boys']){const a=document.getElementById('nav-'+category);if(!a||a.closest('.nav-group'))continue;const group=document.createElement('div');group.className='nav-group';a.before(group);group.append(a);group.insertAdjacentHTML('beforeend',`<button class="category-toggle" aria-label="Explore ${category} categories" aria-expanded="false" aria-controls="menu-${category}" data-v7="category" data-category="${category}">⌄</button><section id="menu-${category}" class="nav-dropdown" aria-label="${category} shopping menu" hidden>${categoryMenu(category)}</section>`);}
 const input=document.getElementById('store-search'),form=input.closest('form');form.insertAdjacentHTML('beforeend','<section id="search-suggestions" class="search-suggestions" aria-label="Search suggestions" hidden></section>');input.setAttribute('aria-controls','search-suggestions');input.setAttribute('aria-expanded','false');input.autocomplete='off';
 input.addEventListener('input',()=>{const q=input.value.trim().toLowerCase(),box=document.getElementById('search-suggestions');if(q.length<2){closeSearchV7();return;}const matches=products.filter(p=>(p.name+' '+p.type+' '+p.category).toLowerCase().includes(q)).slice(0,4);box.innerHTML=`<small>FIND A LITTLE FAVOURITE</small>${matches.length?matches.map((p,i)=>`<a href="${url(p)}" data-action="select-item" data-product="${p.id}" data-index="${i}" data-list="search_suggestions"><img src="${img(p)}" alt=""><span>${p.name}<strong>${money(p.price)}</strong></span><span>↗</span></a>`).join(''):'<p>No matches yet. Try “cotton”, “dress” or “romper”.</p>'}<button type="submit" class="text-button">See all search results →</button>`;box.hidden=false;input.setAttribute('aria-expanded','true');suggestionsOpen=true;});
 input.addEventListener('keydown',e=>{if(e.key==='ArrowDown'&&suggestionsOpen){e.preventDefault();document.querySelector('#search-suggestions a')?.focus();}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeCategoryV7();closeSearchV7();}});
 document.addEventListener('click',e=>{if(!e.target.closest('.nav-group'))closeCategoryV7();if(!e.target.closest('.header-search'))closeSearchV7();});
}
function closeSearchV7(){const box=document.getElementById('search-suggestions'),restore=box?.contains(document.activeElement);if(box)box.hidden=true;if(restore)document.getElementById('store-search')?.focus();document.getElementById('store-search')?.setAttribute('aria-expanded','false');suggestionsOpen=false;}
function closeCategoryV7(){const focusedPanel=document.activeElement?.closest('.nav-dropdown');if(focusedPanel)document.querySelector('[aria-controls="'+focusedPanel.id+'"]').focus();document.querySelectorAll('.nav-dropdown').forEach(x=>x.hidden=true);document.querySelectorAll('.category-toggle').forEach(x=>x.setAttribute('aria-expanded','false'));navOpen='';}
const renderBeforeV7=render;
render=function(){
 const route=window.namaaLocalPath().replace(/\/$/,'');
 if(route==='/instructor/advanced-labs'){currentProduct=undefined;document.getElementById('main').innerHTML=advancedLabsV7();document.title='Extended practice lab | Namaa';updateCounts();setupVideoV7();return;}
 renderBeforeV7();
 if(route==='/instructor')document.querySelector('.page-heading')?.insertAdjacentHTML('afterend',`<nav class="lab-nav"><a class="button secondary" href="/namaa-gtm-classroom/instructor/advanced-labs/">Video, campaigns & AI validation →</a></nav>`);
 if(route==='/instructor/coverage')document.querySelector('.lab-nav')?.insertAdjacentHTML('beforeend','<a class="button secondary" href="/namaa-gtm-classroom/instructor/advanced-labs/">Extended practice →</a>');
 if(route==='/instructor/labs')document.querySelector('.lab-nav')?.insertAdjacentHTML('beforeend','<a href="/namaa-gtm-classroom/instructor/advanced-labs/">Video & AI payload lab →</a>');
 if(route.startsWith('/products/'))enhanceProductV7();
};
function enhanceProductV7(){
 const p=currentProduct;if(!p)return;document.querySelector('.detail-photo')?.insertAdjacentHTML('beforeend','<button class="photo-zoom" data-v7="zoom" aria-label="Enlarge product photo">⤢ Enlarge photo</button>');
 document.getElementById('mobile-product-actions')?.remove();document.body.insertAdjacentHTML('beforeend',`<aside id="mobile-product-actions" class="mobile-product-actions" hidden><span>${p.name}<strong>${money(p.price)}</strong></span><button class="button" data-v7="mobile-add">Choose your size</button></aside>`);
 const original=document.getElementById('add-to-cart'),bar=document.getElementById('mobile-product-actions');const observer=new IntersectionObserver(entries=>{bar.hidden=entries[0].isIntersecting;},{threshold:.2});observer.observe(original);
 const sync=()=>{const b=bar.querySelector('button');b.textContent=variant.size?'Add to cart →':'Choose your size';b.disabled=!!variant.size&&!stock(p,variant.size,variant.colour);};new MutationObserver(sync).observe(document.getElementById('variant-controls'),{childList:true,subtree:true});sync();
}
const goodAuditExample={event:'purchase',event_id:'demo-event-001',demo_mode:true,ecommerce:{transaction_id:'NM-EXAMPLE-001',currency:'EGP',value:592.2,shipping:60,items:[{item_id:'NM-K001',item_name:'Sunshine Cotton Tee',item_variant:'Sky / 4–5y',price:296.1,discount:32.9,quantity:2}]}};
function advancedLabsV7(){return heading('EYOUTH / EXTENDED PRACTICE','More journeys. Better judgement.','Real browser interactions for advanced lessons. Local evidence is separate from GTM and GA4 verification.')+`<nav class="lab-nav"><a href="/namaa-gtm-classroom/instructor/" class="button secondary">Instructor studio</a><a href="/namaa-gtm-classroom/instructor/coverage/" class="button secondary">Course scenario map</a><a href="/namaa-gtm-classroom/instructor/labs/" class="text-link">Forms, history & iframe lab →</a></nav><div class="extended-grid"><section class="panel" id="video-lab"><span class="coverage-status">Working browser fixture</span><h2>A video worth measuring.</h2><p>Play, pause, seek and finish this short, silent CC0 sample. Inspect <code>video_start</code>, <code>video_progress</code>, <code>video_pause</code> and <code>video_complete</code>.</p><video id="lesson-video" controls preload="metadata" playsinline aria-label="Flower motion tracking sample" poster="/assets/video-poster.svg"><source src="/namaa-gtm-classroom/assets/flower-cc0.mp4" type="video/mp4">Your browser cannot play this sample. <a href="/namaa-gtm-classroom/assets/flower-cc0.mp4">Download it</a>.</video><p id="video-status" class="fixture-status" role="status">Ready to play.</p><p class="small-text">Local copy of MDN’s CC0 flower sample. This is a native HTML5 player: GTM’s YouTube trigger will not automatically track it. These event names need your own Custom Event triggers and GA4 tags.</p></section><section class="panel" id="visibility-lab"><span class="coverage-status">Working browser fixture</span><h2>Did they see the advice?</h2><p>Open the panel, then bring at least half of it into view. This emits <code>fit_panel_view</code> once per opening. Compare it with a GTM Element Visibility trigger targeting <code>#fit-advice-panel</code>.</p><button class="button secondary" data-v7="fit-toggle" aria-expanded="false" aria-controls="fit-advice-panel">Show fit advice</button><div id="fit-advice-panel" class="fit-advice" hidden><span>✳</span><h3>A little room to grow.</h3><p>Measure their height and chest. Between sizes? Choose the larger size.</p><a href="/namaa-gtm-classroom/size-guide/" class="text-link">Find their size →</a></div></section><section class="panel" id="campaign-lab"><h2>From campaign to cart.</h2><p>Open a real tagged landing URL and follow it through the store. Only the fixed classroom campaign names below are accepted by this exercise; arbitrary URL values are not added to analytics payloads.</p><a class="button" href="/namaa-gtm-classroom/?utm_source=eyouth&utm_medium=training&utm_campaign=namaa_launch">Open tagged store visit →</a><p>Expected local event: <code>campaign_landing</code>. The event records the landing only; it does not prove attribution, a session source in GA4 or cross-domain continuity.</p><a id="outbound-reference" href="https://example.com/" target="_blank" rel="noopener noreferrer" data-v7="outbound">Open external reference ↗</a><p class="small-text">Outbound example opens a public example domain. Inspect <code>outbound_click</code> without confusing it with a purchase.</p></section><section class="panel" id="ai-payload-lab"><span class="coverage-status">Local deterministic checks</span><h2>AI can draft it. You verify it.</h2><p>Paste a JSON event or event array produced by an AI or exported from the inspector. The checker does not run scripts, call an AI service, send data or modify GTM.</p><label for="payload-input">Event JSON — use redacted examples only</label><textarea id="payload-input" rows="12" maxlength="120000" spellcheck="false">${esc(JSON.stringify(goodAuditExample,null,2))}</textarea><div class="button-row"><button class="button" data-v7="audit">Validate payload</button><button class="button secondary" data-v7="audit-bad">Load broken example</button><button class="text-button" data-v7="audit-good">Restore valid example</button></div><div id="payload-result" class="audit-result" role="status"></div><details><summary>AI prompt to start the exercise</summary><p>Using the Namaa measurement contract, draft a GTM trigger and variable mapping for this event. Explain currency, item price × quantity, consent and duplicate prevention. Give positive and negative tests. Return a proposal for review; do not publish.</p></details><p class="small-text">Passing this checker proves only these schema checks. It does not prove valid GTM configuration, consent compliance, network delivery or GA4 receipt.</p></section></div><section class="panel"><h2>Advanced infrastructure checklist</h2><p>Cross-domain measurement needs a second owned origin and configured GA4 linking. Server-side GTM needs a server container and tagging endpoint. API automation needs authorized credentials and a training workspace. Custom templates need sandbox permissions and review. Those cannot be verified by this static store alone.</p><a class="text-link" href="/namaa-gtm-classroom/instructor/coverage/">Review the complete scenario map →</a></section>`;}
function setupVideoV7(){const v=document.getElementById('lesson-video'),status=document.getElementById('video-status');let started=false,done=false,thresholds=new Set();const payload=percent=>({video_title:'Flower motion tracking sample',video_provider:'namaa_html5_demo',video_duration:round(v.duration||0),video_current_time:round(v.currentTime),video_percent:percent});v.addEventListener('play',()=>{if(done){done=false;started=false;thresholds=new Set();}if(!started){track('video_start',payload(0));started=true;}status.textContent='Playing · inspect the video events in the instructor studio.';});v.addEventListener('timeupdate',()=>{if(!started||v.paused||v.seeking||!v.duration)return;const percent=Math.floor(v.currentTime/v.duration*100);for(const t of [25,50,75])if(percent>=t&&!thresholds.has(t)){thresholds.add(t);track('video_progress',payload(t));}});v.addEventListener('pause',()=>{if(started&&!v.ended){track('video_pause',payload(Math.floor(v.currentTime/v.duration*100)));status.textContent='Paused.';}});v.addEventListener('ended',()=>{if(!done){track('video_complete',payload(100));done=true;}status.textContent='Complete · one completion event for this playback.';});v.addEventListener('error',()=>status.textContent='The sample could not load. Use the local download link and check media support.');}
function bootExperienceV7(){
 setupNavigationV7();
 document.addEventListener('click',e=>{const b=e.target.closest('[data-v7]');if(!b)return;const a=b.dataset.v7;
  if(a==='category'){const c=b.dataset.category,open=navOpen!==c;closeCategoryV7();if(open){navOpen=c;document.getElementById('menu-'+c).hidden=false;b.setAttribute('aria-expanded','true');}}
  if(a==='zoom'){let d=document.getElementById('photo-dialog');if(!d){d=document.createElement('dialog');d.id='photo-dialog';d.setAttribute('aria-label','Enlarged product photo');document.body.append(d);}d.innerHTML=`<button class="icon-button" data-action="close-dialog" aria-label="Close enlarged photo">×</button><img src="${img(currentProduct)}" alt="${currentProduct.name} in ${currentProduct.colours[0]}"><p>Shown in ${currentProduct.colours[0]}</p>`;d.showModal();}
  if(a==='mobile-add'){if(!variant.size){document.getElementById('variant-controls').scrollIntoView({behavior:'smooth',block:'center'});document.querySelector('[data-action="size"]:not(:disabled)')?.focus();}else document.getElementById('add-to-cart').click();}
  if(a==='outbound')track('outbound_click',{link_domain:'example.com',link_id:'outbound-reference'});
  if(a==='fit-toggle'){const p=document.getElementById('fit-advice-panel');p.hidden=!p.hidden;b.setAttribute('aria-expanded',String(!p.hidden));b.textContent=p.hidden?'Show fit advice':'Hide fit advice';fitObserver?.disconnect();if(!p.hidden){fitObserver=new IntersectionObserver(entries=>{if(entries[0].isIntersecting){track('fit_panel_view',{panel_id:'fit-advice-panel'});fitObserver.disconnect();}},{threshold:.5});fitObserver.observe(p);}}
  if(a==='audit-bad')document.getElementById('payload-input').value=JSON.stringify({event:'purchase',ecommerce:{currency:'USD',value:'592.2',items:[{item_name:'Sunshine Cotton Tee',price:296.1,quantity:2}]}},null,2);
  if(a==='audit-good')document.getElementById('payload-input').value=JSON.stringify(goodAuditExample,null,2);
  if(a==='audit'){const out=document.getElementById('payload-result');try{const result=auditEventPayload(JSON.parse(document.getElementById('payload-input').value));out.className='audit-result '+(result.passed?'passed':'failed');out.innerHTML=result.passed?`<strong>Passed these checks · ${result.checked} event(s).</strong><p>Continue with GTM Preview and destination verification.</p>`:`<strong>${result.issues.length} issue(s) to review</strong><ul>${result.issues.map(x=>`<li>Event ${x.row}: ${esc(x.message)}</li>`).join('')}</ul>`;track('payload_audit',{passed:result.passed,events_checked:result.checked,issue_count:result.issues.length});}catch{out.className='audit-result failed';out.textContent='Invalid JSON. Paste an event object or an array, without JavaScript or Markdown fences.';}}
 });
 const q=new URLSearchParams(location.search);if(q.get('utm_source')==='eyouth'&&q.get('utm_medium')==='training'&&q.get('utm_campaign')==='namaa_launch')track('campaign_landing',{campaign_source:'eyouth',campaign_medium:'training',campaign_name:'namaa_launch'});
}

